-- Explicit fixed V2 rollout. Run after the compatible worker creates the new schema.
-- No report, order, or price mutations. Stage inactive rows; one guarded UPDATE switches all 20.
-- Fail closed if the live V1 or staged V2 differs. Reruns never overwrite admin edits.

CREATE TABLE IF NOT EXISTS quiz_release_expectations(release_id TEXT NOT NULL,question_id TEXT NOT NULL,prompt TEXT NOT NULL,options_json TEXT NOT NULL,report_config_json TEXT NOT NULL,PRIMARY KEY(release_id,question_id));










































UPDATE quiz_questions SET active=CASE WHEN id IN ('attachment-style-fixed-v2-q01','attachment-style-fixed-v2-q02','attachment-style-fixed-v2-q03','attachment-style-fixed-v2-q04','attachment-style-fixed-v2-q05','attachment-style-fixed-v2-q06','attachment-style-fixed-v2-q07','attachment-style-fixed-v2-q08','attachment-style-fixed-v2-q09','attachment-style-fixed-v2-q10','attachment-style-fixed-v2-q11','attachment-style-fixed-v2-q12','attachment-style-fixed-v2-q13','attachment-style-fixed-v2-q14','attachment-style-fixed-v2-q15','attachment-style-fixed-v2-q16','attachment-style-fixed-v2-q17','attachment-style-fixed-v2-q18','attachment-style-fixed-v2-q19','attachment-style-fixed-v2-q20') THEN 1 ELSE 0 END,updated_at=CURRENT_TIMESTAMP WHERE test_id='attachment-style' AND (NOT EXISTS(SELECT 1 FROM quiz_catalog_migrations WHERE id='attachment-fixed-v2-2026-10-08') AND (SELECT COUNT(*) FROM quiz_questions WHERE test_id='attachment-style' AND active=1)=20 AND (EXISTS(SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q01' AND test_id='attachment-style' AND active=1 AND prompt='Their replies are shorter than usual today. What happens inside you first?' AND json_array_length(options_json)=4 AND json_extract(options_json,'$[0].label')='I keep checking my phone, then keep sending follow-up texts until they reply.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='I pull my attention back and become less interested in reaching out.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='I notice the change and check in before deciding what it means.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='I want to ask what''s wrong, then hold back because I feel too exposed.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS(SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q02' AND test_id='attachment-style' AND active=1 AND prompt='They cancel a plan you were looking forward to. What is your first response?' AND json_array_length(options_json)=4 AND json_extract(options_json,'$[0].label')='I wonder how important I am to them and want another plan right away.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='I feel disappointed, then decide to expect less and do my own thing.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='I say I''m disappointed and ask whether we can choose another time.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='I act like it doesn''t matter while wanting them to notice that it does.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS(SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q03' AND test_id='attachment-style' AND active=1 AND prompt='They ask for an evening alone after a busy week. What feels most familiar?' AND json_array_length(options_json)=4 AND json_extract(options_json,'$[0].label')='I say okay but look for signs that we''re still close.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='I feel relieved and put off thinking about when we''ll reconnect.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='I can give them space and agree on when we''ll catch up.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='I want to respect the space, then feel hurt and want distance myself.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS(SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q04' AND test_id='attachment-style' AND active=1 AND prompt='You reconnect after a few days apart. How do you usually settle back in?' AND json_array_length(options_json)=4 AND json_extract(options_json,'$[0].label')='I need extra warmth before I can stop wondering if something changed.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='I take a while to let them back into the routine I''ve built alone.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='I enjoy reconnecting and talk about anything that felt off.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='I want closeness, but feel guarded once it''s available again.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS(SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q05' AND test_id='attachment-style' AND active=1 AND prompt='They become more affectionate as the relationship grows. What do you notice?' AND json_array_length(options_json)=4 AND json_extract(options_json,'$[0].label')='I feel happy, but keep asking whether they really care about me.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='I feel uncomfortable and want some distance.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='I feel happy and respond with affection.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='I feel happy at first, then worry they''ll change their mind, so I hold back.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS(SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q06' AND test_id='attachment-style' AND active=1 AND prompt='You''re having a hard week and they offer practical help. What do you do?' AND json_array_length(options_json)=4 AND json_extract(options_json,'$[0].label')='I accept and look for extra signs that they don''t mind helping.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='I usually say I''m fine and handle it myself.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='I tell them what would help and accept what they can offer.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='I want the help, then feel uncomfortable once I''m relying on it.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
