EXISTS(SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q09' AND test_id='attachment-style' AND active=1 AND prompt='A disagreement is getting more tense. What is your usual first move?' AND json_array_length(options_json)=4 AND json_extract(options_json,'$[0].label')='I keep talking because leaving it unresolved feels harder than continuing.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='I get quiet or leave before I can say much about what I feel.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='I ask for a short pause and name when I can return.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='I want them close, then push them away when the feelings get stronger.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS(SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q10' AND test_id='attachment-style' AND active=1 AND prompt='They say something you did hurt them. What do you notice first?' AND json_array_length(options_json)=4 AND json_extract(options_json,'$[0].label')='I worry they''re losing trust in me and hurry to make things okay.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='I focus on explaining my reasons before hearing the whole impact.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='I want to understand what hurt, even if part of me feels defensive.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='I want to repair it but also feel like shutting the conversation down.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS(SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q11' AND test_id='attachment-style' AND active=1 AND prompt='You agreed to come back to a difficult conversation later. What usually happens?' AND json_array_length(options_json)=4 AND json_extract(options_json,'$[0].label')='I reach out before the agreed time because the waiting is hard.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='Once I feel calmer, I hope we won''t need to bring it up again.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='I return at the agreed time, or explain if I need to change it.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='I prepare to talk, then hesitate when the moment to reconnect arrives.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS(SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q12' AND test_id='attachment-style' AND active=1 AND prompt='They apologize after hurting your feelings. What helps you move forward?' AND json_array_length(options_json)=4 AND json_extract(options_json,'$[0].label')='I need more reassurance that they still care about me.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='I say we''re fine but keep some emotional distance.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='I can accept the apology and ask for a specific change if needed.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='I want to accept it but move between trust and expecting another hurt.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS(SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q13' AND test_id='attachment-style' AND active=1 AND prompt='They want to see you tonight, but you need time to yourself. What do you do?' AND json_array_length(options_json)=4 AND json_extract(options_json,'$[0].label')='I consider saying yes because I worry a no will disappoint them.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='I make myself unavailable without saying much about why.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='I say I need the evening and suggest another time if I want one.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='I want them to want me, yet feel tense about agreeing to the plan.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS(SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q14' AND test_id='attachment-style' AND active=1 AND prompt='You wish they would check in more often. How do you bring it up?' AND json_array_length(options_json)=4 AND json_extract(options_json,'$[0].label')='I hint at it and watch for signs they''ll offer without being asked.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='I tell myself it shouldn''t matter and try to need less.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='I describe what would feel good and ask what works for them.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='I start to ask, then soften it so much that the need disappears.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS(SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q15' AND test_id='attachment-style' AND active=1 AND prompt='You discover a preference that matters to you is different from theirs. What follows?' AND json_array_length(options_json)=4 AND json_extract(options_json,'$[0].label')='I feel tempted to change mine so we don''t become less close.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='I take it as a reason to keep more of my life separate.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='I can stay curious and see where we can meet without agreeing on everything.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='I want to compromise, then worry I''m giving up too much of myself.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS(SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q16' AND test_id='attachment-style' AND active=1 AND prompt='They''ve had a rough day and want to talk. What is your first reaction?' AND json_array_length(options_json)=4 AND json_extract(options_json,'$[0].label')='I feel responsible for helping them feel better quickly.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='I move into advice or practical fixes rather than staying with the feeling.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='I ask whether they want listening, help, or a little space.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='I want to comfort them but also feel overwhelmed and want to step back.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS(SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q17' AND test_id='attachment-style' AND active=1 AND prompt='The relationship has felt steady for several weeks. What do you notice?' AND json_array_length(options_json)=4 AND json_extract(options_json,'$[0].label')='I still look for reassurance that the warmth hasn''t started to fade.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='I begin noticing reasons I might want more distance.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='I feel able to enjoy the relationship and the rest of my life.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='I enjoy the calm but catch myself bracing for it to change.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS(SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q18' AND test_id='attachment-style' AND active=1 AND prompt='They spend an evening with friends while you do your own thing. What feels familiar?' AND json_array_length(options_json)=4 AND json_extract(options_json,'$[0].label')='I have trouble settling unless we check in during the evening.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='I feel most comfortable when our plans don''t depend on each other.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='I can enjoy separate plans and look forward to catching up.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='I want the independence, then feel unexpectedly left out once we''re apart.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS(SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q19' AND test_id='attachment-style' AND active=1 AND prompt='You realize you made a mistake in the relationship. What do you tend to do?' AND json_array_length(options_json)=4 AND json_extract(options_json,'$[0].label')='I apologize repeatedly and need to know they still want me.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='I focus on fixing the practical part and avoid discussing how it felt.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='I own what I did, listen to the impact, and follow through on a change.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='I want to make amends but feel like hiding before they can respond.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS(SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q20' AND test_id='attachment-style' AND active=1 AND prompt='After a reassuring conversation, how long does the reassurance stay with you?' AND json_array_length(options_json)=4 AND json_extract(options_json,'$[0].label')='It helps briefly, then a small change makes me need it again.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='I feel calmer mainly once I have some time to myself.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='It usually stays with me unless something new gives me a reason to worry.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='Part of me believes it while another part stays ready to pull away.' AND json_extract(options_json,'$[3].styleKey')='fearful')) AND ((SELECT COUNT(*) FROM quiz_release_expectations WHERE release_id='attachment-fixed-v2-2026-10-08')=20 AND NOT EXISTS(SELECT 1 FROM quiz_release_expectations e LEFT JOIN quiz_questions q ON q.id=e.question_id WHERE e.release_id='attachment-fixed-v2-2026-10-08' AND (q.id IS NULL OR q.test_id!='attachment-style' OR q.active!=0 OR q.prompt!=e.prompt OR q.options_json!=e.options_json OR q.report_config_json IS NULL OR q.report_config_json!=e.report_config_json))) AND EXISTS(SELECT 1 FROM quiz_report_templates WHERE version='attachment-fixed-v2' AND content_json='{"version":"attachment-fixed-v2","revision":1,"profiles":{"anxious":{"label":"Anxious attachment","headline":"You care deeply. Feeling sure is the harder part.","summary":"Small changes in contact can take up a lot of space in your mind. You may want to talk, check, and make sure you still matter. Reassurance can help in the moment, while the next unanswered message brings the question back.","traits":["You notice changes in warmth or contact quickly.","Unfinished conversations can be hard to leave alone.","You may seek reassurance more than once.","A response can settle you briefly without making the worry disappear.","You can put the connection ahead of your own rest or limits."],"risks":[{"id":"anxious-unfinished","title":"When you keep reaching and the conversation never comes back","preview":"A disagreement can turn into hours of waiting for proof that you still matter.","paragraphs":["A pause with a clear return can give both people breathing room. A repeated pattern of disappearing without returning leaves a different task on your shoulders: you are left to work out whether there is still a conversation, or even a relationship, to return to.","If your familiar response is to keep asking, the uncertainty can make each message feel necessary. You may explain more, soften your words, or apologize for having brought it up. The original issue can disappear beneath the effort to restore contact.","The cost is not simply that you sent several messages. It is that having a need begins to feel dangerous, while getting any reply starts to feel like a successful repair. Contact has resumed, but what hurt you may still be untouched."]},{"id":"anxious-warmth","title":"Why a little warmth can keep you waiting","preview":"Relief can feel so good that the repeated disappointment becomes harder to evaluate.","paragraphs":["After a period of distance, one affectionate conversation can feel disproportionately important. It restores something you have been trying to reach, and it may make the relationship feel promising again before much has changed in practice.","This can become especially tiring when agreements are warm but rarely followed through. You may keep measuring the relationship by the best return of affection, rather than by the pattern you live with between those moments.","Warmth is meaningful. Its return alone does not tell you whether the underlying problem is changing. A relationship can contain real affection and still leave your needs repeatedly waiting."]},{"id":"anxious-repair","title":"When keeping the peace becomes your job","preview":"You may be repairing the connection so quickly that your own hurt never gets a turn.","paragraphs":["You might be the person who reaches out first, adjusts the wording, and looks for a way to make things feel okay. That effort can preserve a conversation. Repeatedly carrying it alone can also teach the relationship that your discomfort will eventually make you do the repair work.","Over time, you may become more careful about raising concerns. You know how much effort it takes to return to normal, so a reasonable need begins to feel like a problem you should manage privately.","The quieter loss is confidence in your own perspective. Being able to restore closeness does not mean your need was unreasonable, and agreeing to end a disagreement does not prove the disagreement was resolved."]}],"deeper":[{"id":"anxious-reassurance","title":"Why reassurance can fade so quickly","preview":"One answer can settle this moment without settling what the next silence means to you.","paragraphs":["A reassuring answer addresses the worry you brought into a particular conversation. It may not change the expectation you carry into the next one: will support still be there when I need it again? That is why feeling better now and checking again later can coexist.","Your answers show where this happens, rather than proving you distrust everyone. It may be strongest around messages, unfinished conflict, or a request you are afraid will be refused. Different situations can bring out different responses.","Repeated inconsistency from another person also matters. The same urge to check can occur when there is little new evidence, or when someone actually keeps breaking agreements. Your relationship-background answers help separate those possibilities."]},{"id":"anxious-cost","title":"What you may slowly stop allowing yourself","preview":"The relationship can take up more space while your own limits become harder to hear.","paragraphs":["If keeping the bond intact becomes the first priority, your attention may stay on what will reassure the other person or prevent another withdrawal. Rest, disagreement, and a clear no can begin to feel expensive.","You may still function well in the rest of your life while one relationship consumes a surprising amount of thought. This does not make the relationship more meaningful by itself; it describes how much work uncertainty is asking you to do.","The important distinction in this report is between caring about someone and repeatedly abandoning your own experience to keep contact. Your selected answers show where that pressure is most familiar."]}]},"avoidant":{"label":"Avoidant attachment","headline":"You know how to carry it alone. Letting someone in is less familiar.","summary":"You often turn toward yourself when feelings are difficult, and create space when closeness becomes demanding. Other people may see independence without realizing that you also have needs you rarely bring into the conversation.","traits":["You tend to process difficult feelings on your own.","You may lower your expectations before asking for more.","After sharing something personal, you can want to close the conversation down.","Closeness can feel pressuring when you cannot see enough room for yourself.","Once you feel calmer, you may hope the difficult subject will pass."],"risks":[{"id":"avoidant-pressure","title":"When closeness starts to feel like a demand","preview":"The more urgently someone asks for access, the less you may feel able to speak.","paragraphs":["If someone repeatedly demands immediate answers, more contact, or disclosures you are not ready to make, closeness can start to feel like losing control over your own time and feelings. Creating distance may bring immediate relief.","A loop can form if they respond to that distance by pressing harder. You may speak less because you feel pushed; they may push because you speak less. Each person reacts to the last move, while the actual need underneath becomes harder to hear.","Needing space does not by itself make you unavailable. The risk grows when no pause is allowed, or when withdrawing becomes the only response and there is never a return. Both the pressure and the follow-through matter."]},{"id":"avoidant-silent","title":"The distance that grows while everything looks calm","preview":"Not arguing can feel peaceful even while important things stay unsaid.","paragraphs":["You may feel that an issue has passed once the intensity inside you settles. The other person may still be waiting to understand what happened or whether it will happen again. You can be in the same room and be at very different points in the conversation.","When this repeats, they may ask less, and you may feel relieved that there is less tension. But fewer questions can also mean that someone has stopped expecting an answer. Quiet is not enough information to tell those situations apart.","The cost can arrive late: emotional distance that seemed sudden has actually grown around a series of unfinished moments. Your conflict and return-to-conversation answers indicate whether this is a familiar risk for you."]},{"id":"avoidant-needs","title":"When needing less starts to cost you more","preview":"People can only respond to the needs they have some chance to understand.","paragraphs":["Telling yourself that you should not need so much can keep a relationship feeling undemanding. It can also remove the opportunity to find out whether this person would respond differently if they knew what you wanted.","You may become skilled at adjusting privately: expecting less contact, not mentioning disappointment, or solving a difficult week alone. Other people can mistake those adjustments for genuine preference. They may not know how much effort it takes to seem fine.","The cost is not only missed support. It can be resentment that has no shared explanation: you feel alone in carrying things, while the other person has never understood how alone you feel. Respect for your privacy and room for your needs both matter."]}],"deeper":[{"id":"avoidant-reliance","title":"When did relying on yourself become the only real option?","preview":"Your family answers help distinguish a familiar habit of self-reliance from a history we should not assume.","paragraphs":["Some people remember asking caregivers for help and repeatedly finding that the support they needed was not available. Over time, asking can begin to feel pointless: the problem will still be theirs to handle. If you selected that experience, the matching family section explores it directly.","Others remember reliable early care and became more guarded after a later relationship, or simply recognize a present habit without identifying one clear origin. Being avoidant in these answers cannot tell us which family you came from. Your actual background choices determine what follows.","What the current answers can show is the move toward handling things privately. Being capable and feeling able to ask are different experiences. A person can be good at carrying a problem and still rarely experience help as a real option."]},{"id":"avoidant-guard","title":"Why “you can rely on me” may not feel reassuring yet","preview":"An offer can be sincere and still feel unfamiliar to receive.","paragraphs":["An offer of support can create questions before it creates relief. Will they understand? Will I still have room to decide what I share? What happens if I let myself expect something and it does not arrive? Which of these fits depends on your selected reactions and experiences.","You may keep part of the story private, accept practical help while withholding the feeling, or retreat after a moment of disclosure. Each move keeps the amount of dependence manageable. It can also make it difficult for another person to discover how to be there for you.","The result is a relationship in which you may be cared about without often feeling cared for. This is a possible consequence of the responses you selected, not proof that every offer is safe or that every limit should be removed."]}]},"fearful":{"label":"Fearful-avoidant attachment","headline":"You want to be close, and keep a way to protect yourself.","summary":"You may reach for connection and then feel exposed when it arrives. A need comes out and is taken back; distance feels safer until you begin to miss the person. Wanting care and wanting protection can show up in the same moment.","traits":["You can want contact and hesitate to show how much.","Affection may bring relief followed by worry.","You may regret sharing soon after feeling understood.","Commitment can be wanted and unsettling at the same time.","Pulling away can be followed by a renewed fear of losing the connection."],"risks":[{"id":"fearful-shift","title":"When each change in direction starts another test","preview":"You move closer, feel exposed, and pull back; the response can restart the worry.","paragraphs":["Reaching out can briefly answer the fear of being forgotten. Being received can raise another concern: now this person can see how much they matter. Pulling back then reduces the exposure while creating fresh distance.","The other person may respond to that distance with their own uncertainty, urgency, or withdrawal. You can end up reacting to a response that your last protective move helped create. That does not make the whole relationship your responsibility; it describes one possible feedback loop.","Over time, both people can spend more effort interpreting each other than saying what they mean. Small delays and changes of tone become tests, and neither person feels sure which version of the connection will appear next."]},{"id":"fearful-unpredictable","title":"When unpredictable care keeps you on watch","preview":"A good moment can feel real without becoming a stable expectation.","paragraphs":["If another person sometimes responds warmly and sometimes shuts you out or dismisses your needs, it is difficult to know what opening up will lead to. Feeling relieved during one conversation may not help you predict the next.","For someone who already recognizes both reaching and retreating, that uncertainty can reinforce the urge to keep an exit available. You may be moved by care and quickly look for signs that it is about to change.","The cost can be losing the chance to rest in either direction. Staying close requires monitoring; staying distant brings longing. Your partner-response answers indicate whether this unpredictability is something you actually described, rather than something a label allows us to assume."]},{"id":"fearful-unheard","title":"When your request is hidden by what you do next","preview":"The person may hear “leave me alone” when the feeling underneath is much less simple.","paragraphs":["You may ask for reassurance and then dismiss it, agree to meet and want to cancel, or share something personal and quickly change the subject. Each response can make sense as protection in the moment. Taken together, they can make your request hard to recognize.","The other person may stop offering the thing you hoped for because they understand the withdrawal as a clear no. Or they may keep pressing, which can feel intrusive. Neither outcome automatically explains what you actually wanted.","The hidden cost is the feeling of being misunderstood while only part of the need has been visible. The specific answers you chose show where that split is most familiar, rather than treating every disagreement as the same problem."]}],"deeper":[{"id":"fearful-both","title":"Why distance and closeness can both unsettle you","preview":"The wish for support does not always cancel the wish to stay protected.","paragraphs":["Distance may raise the possibility of losing someone. Closeness may raise the possibility of relying on them, being seen, or being hurt later. If both concerns become active, neither moving forward nor pulling back feels fully settled.","This can make your own reactions seem inconsistent to you. A warm evening may be followed by wanting space; wanting space may be followed by checking whether they still care. The sequence matters more than treating any one moment as the whole story.","This result describes the approach-and-retreat reactions in your choices. It does not establish a childhood diagnosis or tell us that a particular harmful event occurred. Family and later-experience sections use only the backgrounds you actually selected."]},{"id":"fearful-trust","title":"Why reassurance and trust may move at different speeds","preview":"You can believe the caring words for a moment and still keep protecting yourself.","paragraphs":["A reassuring sentence can reach the part of you that wants connection. The part that anticipates hurt may still want more information. Both reactions can be present without either one being a performance.","If you have selected experiences of criticism, unpredictable responses, or trust not being respected, those passages explore possible links. If you selected steady care instead, the report preserves that too; it will not replace it with a more dramatic story.","The relationship cost appears when protection happens so quickly that a reliable response never has time to become part of your expectations. Actual repeated inconsistency is different, and should not be explained away as only your difficulty trusting."]}]},"secure":{"label":"Secure attachment","headline":"You can care about the relationship and keep room for yourself.","summary":"You tend to express what you need, allow room for time apart, and return to difficult conversations. You can still feel hurt or uncertain, while using what actually happens to judge the relationship instead of having to re-establish your worth each time.","traits":["You can make a need specific enough to discuss.","Time apart can coexist with a clear plan to reconnect.","You can accept support while choosing what to share.","A disagreement does not have to end the conversation.","Reliable follow-through can become part of your trust."],"risks":[{"id":"secure-promises","title":"When your willingness to understand keeps meeting the same broken promise","preview":"Being able to see their perspective does not make repeated non-delivery harmless.","paragraphs":["You may be able to consider reasons, allow time, and avoid jumping to the worst conclusion. Those responses can support a relationship in which both people act in good faith. They can also leave you waiting if explanations keep replacing actual follow-through.","A calm response from you does not change whether an agreement was kept. If the same disappointment repeats, understanding the circumstances and acknowledging the pattern are both relevant. You do not have to become more visibly distressed before a need counts.","The cost can be patience that slowly stops feeling chosen. This risk is especially relevant if your background answers describe promises without action; the report does not assume that your partner behaves this way."]},{"id":"secure-one-sided","title":"When being good at communication becomes doing it for both people","preview":"A relationship can look workable because you keep making the conversations happen.","paragraphs":["You may be willing to listen, name your part, and return after a pause. If only one person consistently does these things, the relationship can still become uneven. Your ability to restore contact does not show that responsibility is being shared.","Over time, the work may become almost invisible: finding the right moment, clarifying the misunderstanding, raising the unresolved issue again. You can remain composed while becoming tired of carrying the process.","The relevant question is whether there is participation from the other side. Someone can need time or communicate differently and still return, listen, and follow through. Permanent absence from that work is a different pattern."]},{"id":"secure-boundaries","title":"When small exceptions slowly become a relationship you did not agree to","preview":"Flexibility can feel generous until your own limits are repeatedly the part that moves.","paragraphs":["A flexible response can help two people find an arrangement that works. If the same person always adjusts, the exception can quietly become the expectation. You may notice the strain only after the arrangement has been repeated many times.","Being secure in these answers does not make every relationship suitable for you. A reasonable need can remain unmet even when you express it clearly. The other person may be unable or unwilling to offer what the relationship requires.","The cost is treating your ability to cope as evidence that the arrangement is acceptable. How well you handle disappointment and whether you want to keep living with it are separate questions."]}],"deeper":[{"id":"secure-room","title":"What a steadier expectation of support makes possible","preview":"You can have a need without making the whole relationship depend on one immediate response.","paragraphs":["Your selected answers suggest that a pause, a disagreement, or a limit can remain a specific event rather than immediately becoming a judgment about your value. This leaves more room to hear explanations and notice what happens next.","That does not mean you feel calm at every moment. You can be upset, need reassurance, and want someone to show up. The difference in these choices is the room to express the need and consider the response without having only one way to protect yourself.","The family section may describe reliable early support if you selected it. Later consistent care can also be part of the story. Your present responses do not prove that childhood was perfect or that difficult experiences were absent."]},{"id":"secure-reality","title":"Trust can include noticing when something does not work","preview":"Being open does not require you to turn every disappointment into a misunderstanding.","paragraphs":["Trust lets you use reliable experience instead of starting over at every uncertain moment. It also leaves room for new information. Someone repeatedly failing to return or respect a clear limit is information, even if you can understand why they struggle.","Your steadier responses are useful because they make the relationship easier to see, not because they guarantee it will succeed. The report pairs them with your actual descriptions of the other person so that genuine reliability and repeated difficulty remain distinct.","You can value a relationship without making your ability to tolerate it the only measure of whether it works. The needs you can express clearly still deserve an answer."]}]}}}') AND EXISTS(SELECT 1 FROM quiz_tests WHERE id='attachment-style' AND active=1 AND report_price_cents>=0));

UPDATE quiz_tests SET title='Attachment Style Quiz: Your Relationship Patterns',kicker='A closer look at how you connect',description='Explore your reactions in close relationships, the patterns your choices reveal, and the experiences that may help explain them. 14 reaction questions and six optional context questions. See your free result, with an optional complete reading.',presentation_mode='text',updated_at=CURRENT_TIMESTAMP WHERE id='attachment-style' AND ((SELECT COUNT(*) FROM quiz_questions WHERE test_id='attachment-style' AND active=1)=20 AND (SELECT COUNT(*) FROM quiz_questions WHERE test_id='attachment-style' AND active=1 AND id IN ('attachment-style-fixed-v2-q01','attachment-style-fixed-v2-q02','attachment-style-fixed-v2-q03','attachment-style-fixed-v2-q04','attachment-style-fixed-v2-q05','attachment-style-fixed-v2-q06','attachment-style-fixed-v2-q07','attachment-style-fixed-v2-q08','attachment-style-fixed-v2-q09','attachment-style-fixed-v2-q10','attachment-style-fixed-v2-q11','attachment-style-fixed-v2-q12','attachment-style-fixed-v2-q13','attachment-style-fixed-v2-q14','attachment-style-fixed-v2-q15','attachment-style-fixed-v2-q16','attachment-style-fixed-v2-q17','attachment-style-fixed-v2-q18','attachment-style-fixed-v2-q19','attachment-style-fixed-v2-q20'))=20) AND NOT EXISTS(SELECT 1 FROM quiz_catalog_migrations WHERE id='attachment-fixed-v2-2026-10-08');

INSERT OR IGNORE INTO quiz_catalog_migrations(id) SELECT 'attachment-fixed-v2-2026-10-08' WHERE (SELECT COUNT(*) FROM quiz_questions WHERE test_id='attachment-style' AND active=1)=20 AND (SELECT COUNT(*) FROM quiz_questions WHERE test_id='attachment-style' AND active=1 AND id IN ('attachment-style-fixed-v2-q01','attachment-style-fixed-v2-q02','attachment-style-fixed-v2-q03','attachment-style-fixed-v2-q04','attachment-style-fixed-v2-q05','attachment-style-fixed-v2-q06','attachment-style-fixed-v2-q07','attachment-style-fixed-v2-q08','attachment-style-fixed-v2-q09','attachment-style-fixed-v2-q10','attachment-style-fixed-v2-q11','attachment-style-fixed-v2-q12','attachment-style-fixed-v2-q13','attachment-style-fixed-v2-q14','attachment-style-fixed-v2-q15','attachment-style-fixed-v2-q16','attachment-style-fixed-v2-q17','attachment-style-fixed-v2-q18','attachment-style-fixed-v2-q19','attachment-style-fixed-v2-q20'))=20;

DELETE FROM quiz_release_expectations WHERE release_id='attachment-fixed-v2-2026-10-08';

SELECT COUNT(*) AS active_questions,SUM(CASE WHEN id IN ('attachment-style-fixed-v2-q01','attachment-style-fixed-v2-q02','attachment-style-fixed-v2-q03','attachment-style-fixed-v2-q04','attachment-style-fixed-v2-q05','attachment-style-fixed-v2-q06','attachment-style-fixed-v2-q07','attachment-style-fixed-v2-q08','attachment-style-fixed-v2-q09','attachment-style-fixed-v2-q10','attachment-style-fixed-v2-q11','attachment-style-fixed-v2-q12','attachment-style-fixed-v2-q13','attachment-style-fixed-v2-q14','attachment-style-fixed-v2-q15','attachment-style-fixed-v2-q16','attachment-style-fixed-v2-q17','attachment-style-fixed-v2-q18','attachment-style-fixed-v2-q19','attachment-style-fixed-v2-q20') THEN 1 ELSE 0 END) AS fixed_questions FROM quiz_questions WHERE test_id='attachment-style' AND active=1;
