INSERT INTO quiz_release_expectations(release_id,question_id,prompt,options_json,report_config_json) VALUES ('attachment-fixed-v2-2026-10-08','attachment-style-fixed-v2-q01','They usually keep in touch, but you have not heard from them for several hours. What do you do first?','[{"optionId":"q01-a","label":"I keep checking my phone, then send a few more messages.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q01-a","tag":"reassurance","title":"Waiting makes it hard to put your phone down","reading":"When contact stops, it can be hard to bring your attention back to your own day. Sending another message may be your way of checking that the connection is still there.","preview":"When contact stops, it can be hard to bring your attention back to your own day.","reviewZh":{"label":"反复看手机，又忍不住接着发几条消息。","reading":"当联系突然停下来，你很难把注意力放回自己的生活。你可能通过继续发消息，尽快确认你们之间没有出问题。"}}},{"optionId":"q01-b","label":"I pull my attention back and feel less interested in reaching out.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q01-b","tag":"distance","title":"You lower your expectations before you get more invested","reading":"When a reply does not come, you lower your expectations. Pulling back your attention can help you feel less affected by what the other person does.","preview":"When a reply does not come, you lower your expectations.","reviewZh":{"label":"把注意力收回来，也不太想主动联系了。","reading":"当回应没有出现，你会先把期待降下来。与其一直等，你更习惯收回投入，让自己的心情少受对方影响。"}}},{"optionId":"q01-c","label":"I check in once, then get on with what I am doing.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q01-c","tag":"space","title":"You can keep living your day while you wait","reading":"You notice the change and can leave room for a reply. This pause alone is not enough for you to decide that something is wrong between you.","preview":"You notice the change and can leave room for a reply.","reviewZh":{"label":"问候一次，然后继续忙自己的事。","reading":"你会在意联系的变化，也能留出等待的空间。这一次没有回复，暂时还不足以让你认定关系出了问题。"}}},{"optionId":"q01-d","label":"I want to message again, but hold back because I do not want to seem too invested.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q01-d","tag":"push-pull","title":"You want contact and hesitate to show it","reading":"You want to know the connection is still there, and you also want to protect how much you reveal. Your phone may stay quiet while you keep going back and forth inside.","preview":"You want to know the connection is still there, and you also want to protect how much you reveal.","reviewZh":{"label":"很想再发消息，却又怕显得太在乎，最后忍着不发。","reading":"你想确认联系还在，也想保护自己不被看出有多在意。手机上看起来安静，心里却可能一直在犹豫。"}}},{"optionId":"q01-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q01-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Contact and distance","sourceNumber":1}') ON CONFLICT(release_id,question_id) DO NOTHING;
INSERT INTO quiz_release_expectations(release_id,question_id,prompt,options_json,report_config_json) VALUES ('attachment-fixed-v2-2026-10-08','attachment-style-fixed-v2-q02','They cancel a plan, explain why, and suggest another day. What tends to happen for you?','[{"optionId":"q02-a","label":"I still wonder whether I matter as much as I thought.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q02-a","tag":"reassurance","title":"A changed plan makes you question your place","reading":"Even with an explanation, disappointment can turn into a question about your place in the relationship. What matters is not only the missed plan, but whether you are being kept in mind.","preview":"Even with an explanation, disappointment can turn into a question about your place in the relationship.","reviewZh":{"label":"还是忍不住想：我是不是没那么重要？","reading":"即使对方给出解释，失望也可能很快变成对自己位置的怀疑。你在意的不只是这次见面，而是自己有没有被放在心上。"}}},{"optionId":"q02-b","label":"I lower my expectations and prefer to make my own plans next time.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q02-b","tag":"distance","title":"You expect less so the next letdown hurts less","reading":"One disappointment can make you adjust how much you expect. Taking your plans back into your own hands may feel easier than depending on the next agreement.","preview":"One disappointment can make you adjust how much you expect.","reviewZh":{"label":"降低期待，后面尽量自己安排，不太想再依赖约定。","reading":"一次落空可能让你迅速调整投入：之后少期待一点，就不用再被同样的事影响。你会先把生活安排重新放回自己手里。"}}},{"optionId":"q02-c","label":"I feel disappointed, but can agree on a new time.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q02-c","tag":"repair","title":"You consider the explanation and the follow-through","reading":"You can acknowledge your disappointment while considering the explanation and what happens next. A cancelled plan does not immediately become a verdict on the whole relationship.","preview":"You can acknowledge your disappointment while considering the explanation and what happens next.","reviewZh":{"label":"有些失望，但可以商量好新的时间。","reading":"你能承认自己失望，也愿意结合解释和后续行动判断。取消一次计划，没有立刻变成对整段关系的否定。"}}},{"optionId":"q02-d","label":"I agree to reschedule but want to pull away, then look forward to seeing them again.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q02-d","tag":"push-pull","title":"You want the meeting and hesitate to look forward to it","reading":"You still want to see them, but hesitate to get your hopes up again. Wanting closeness and wanting protection can take turns around the same plan.","preview":"You still want to see them, but hesitate to get your hopes up again.","reviewZh":{"label":"答应改时间，心里却想退开；临近见面又很期待。","reading":"你依然想见对方，却不太敢重新投入期待。想靠近和怕再次落空，会在这一次安排里轮流出现。"}}},{"optionId":"q02-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q02-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Contact and distance","sourceNumber":2}') ON CONFLICT(release_id,question_id) DO NOTHING;
INSERT INTO quiz_release_expectations(release_id,question_id,prompt,options_json,report_config_json) VALUES ('attachment-fixed-v2-2026-10-08','attachment-style-fixed-v2-q03','After a busy week, they ask for an evening alone. What feels most familiar?','[{"optionId":"q03-a","label":"I say okay, but look for signs that they are not pulling away.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q03-a","tag":"reassurance","title":"You give space while checking the connection","reading":"You can agree to give space while still needing a sign that the relationship has not changed. Time apart may draw your attention toward whether the closeness is still there.","preview":"You can agree to give space while still needing a sign that the relationship has not changed.","reviewZh":{"label":"嘴上说好，还是想确认对方没有疏远我。","reading":"你可以答应给空间，但心里可能仍需要一个关系没有变化的信号。对方暂时离开时，你更容易留意亲密感是不是还在。"}}},{"optionId":"q03-b","label":"I feel relieved and do not hurry to arrange our next contact.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q03-b","tag":"distance","title":"Distance feels easier than arranging the next connection","reading":"Some distance feels comfortable, and reconnecting can become easy to put off. What matters is whether that delay keeps happening, rather than enjoying one evening to yourself.","preview":"Some distance feels comfortable, and reconnecting can become easy to put off.","reviewZh":{"label":"松了一口气，也不急着安排下一次联系。","reading":"分开一会儿会让你更自在，你也容易把重新联系往后放。要看的是这种延后是否反复出现，而不只是这一次享受独处。"}}},{"optionId":"q03-c","label":"I let them rest and agree on when we will catch up.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q03-c","tag":"space","title":"Space and connection can coexist for you","reading":"You can make room for space and connection together. A clear next point of contact lets you return to your own plans without treating an evening apart as rejection.","preview":"You can make room for space and connection together.","reviewZh":{"label":"让对方休息，顺便约好之后什么时候联系。","reading":"你能同时照顾彼此的空间和联系。分开一晚不会自动意味着疏远，有一个清楚的约定就能让你继续自己的安排。"}}},{"optionId":"q03-d","label":"I want to respect the space, then feel hurt and want distance myself.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q03-d","tag":"push-pull","title":"You want to give space, then pull back further","reading":"You want them to feel comfortable, but the request can also land as rejection. Pulling away in return may protect you from feeling like the one who needs the relationship more.","preview":"You want them to feel comfortable, but the request can also land as rejection.","reviewZh":{"label":"想尊重对方，但又觉得受伤，转而也不想理对方。","reading":"你想让对方自在，也会把这次分开感受成一种拒绝。为了不显得自己更需要关系，你可能跟着把距离拉大。"}}},{"optionId":"q03-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q03-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Contact and distance","sourceNumber":3}') ON CONFLICT(release_id,question_id) DO NOTHING;
INSERT INTO quiz_release_expectations(release_id,question_id,prompt,options_json,report_config_json) VALUES ('attachment-fixed-v2-2026-10-08','attachment-style-fixed-v2-q04','As the relationship grows, they become more affectionate and attentive. What do you usually notice?','[{"optionId":"q04-a","label":"I feel happy, but keep checking whether they really care.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q04-a","tag":"reassurance","title":"You enjoy care and want to know it will last","reading":"The attention feels good, yet it may be hard to stay with that moment. You also want to know whether the affection will continue instead of fading soon.","preview":"The attention feels good, yet it may be hard to stay with that moment.","reviewZh":{"label":"很开心，还是想反复确认对方是不是真的在乎。","reading":"关心会让你开心，但你可能很难只停留在这一刻。你还想确认，这份喜欢能不能继续，而不是很快就变淡。"}}},{"optionId":"q04-b","label":"I feel uncomfortable and want a little less contact.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q04-b","tag":"distance","title":"More closeness can make you want more room","reading":"More closeness can make your own space feel smaller. Less contact may help you feel comfortable again, while leaving them uncertain about how close you want to be.","preview":"More closeness can make your own space feel smaller.","reviewZh":{"label":"有些不自在，想少联系一点，留出距离。","reading":"亲密增加时，你可能先感觉自己的空间变小了。减少联系会让你恢复自在，却也可能让对方摸不清你愿意靠近到哪里。"}}},{"optionId":"q04-c","label":"I feel happy and naturally respond with affection.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q04-c","tag":"closeness","title":"You can receive affection and respond to it","reading":"You can receive care and express your own affection. In this situation, closeness tends to feel like something you can take part in and enjoy.","preview":"You can receive care and express your own affection.","reviewZh":{"label":"开心，也自然地回应对方的亲近。","reading":"你可以接受关心，也愿意表达自己的喜欢。此刻的亲近对你来说，通常是可以参与和享受的。"}}},{"optionId":"q04-d","label":"I feel happy at first, then worry they will change their mind and hold back.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q04-d","tag":"push-pull","title":"Feeling close can bring the fear of losing it","reading":"Care can move you and then make you more watchful. As the relationship matters more, the possibility of losing it can feel more difficult to face.","preview":"Care can move you and then make you more watchful.","reviewZh":{"label":"一开始开心，随后担心对方变心，又把自己收回去。","reading":"你会被关心打动，也可能在打动之后开始防备。越感到这段关系重要，你越怕投入后承受失去。"}}},{"optionId":"q04-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q04-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Closeness and support","sourceNumber":5}') ON CONFLICT(release_id,question_id) DO NOTHING;
INSERT INTO quiz_release_expectations(release_id,question_id,prompt,options_json,report_config_json) VALUES ('attachment-fixed-v2-2026-10-08','attachment-style-fixed-v2-q05','You have had a hard day. Someone you trust offers to listen without trying to fix it. What do you do?','[{"optionId":"q05-a","label":"I talk, but keep worrying that I am becoming a burden.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q05-a","tag":"burden","title":"You share your hurt while worrying you are too much","reading":"Even with someone willing to listen, you may monitor how much space you are taking. You need support and also worry about what needing it will do to their view of you.","preview":"Even with someone willing to listen, you may monitor how much space you are taking.","reviewZh":{"label":"会说，但一直担心自己是不是让对方觉得烦。","reading":"即使对方愿意听，你也可能一边表达，一边检查自己有没有占用太多。你需要支持，也在意表达需要会不会影响对方对你的看法。"}}},{"optionId":"q05-b","label":"I say I am fine and would rather deal with it myself.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q05-b","tag":"self-reliance","title":"Even when help is offered, you turn to yourself first","reading":"When someone offers to listen, you still turn toward a familiar response: getting through it yourself. Asking for support may feel less natural than carrying the feeling alone.","preview":"When someone offers to listen, you still turn toward a familiar response: getting through it yourself.","reviewZh":{"label":"说自己没事，还是更习惯自己消化。","reading":"有人愿意听时，你仍会先回到熟悉的处理方式：自己撑过去。开口求助对你来说，可能比独自消化更不习惯。"}}},{"optionId":"q05-c","label":"I share what I want to share and let them be there.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q05-c","tag":"support","title":"You can accept support and keep your own boundaries","reading":"You can choose how much to disclose and allow someone to support you. Accepting company does not mean handing over all your privacy or your ability to handle the problem.","preview":"You can choose how much to disclose and allow someone to support you.","reviewZh":{"label":"说出愿意分享的部分，让对方陪我一会儿。","reading":"你可以决定分享多少，也允许别人参与支持。接受陪伴并不要求你交出全部隐私或解决问题的主动权。"}}},{"optionId":"q05-d","label":"I start to talk, then pull back when it begins to feel vulnerable.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q05-d","tag":"push-pull","title":"You want understanding and fear being seen too closely","reading":"You want to be understood, yet being seen can also feel unsettling. After letting them a little closer, you may want to take something back so you feel protected again.","preview":"You want to be understood, yet being seen can also feel unsettling.","reviewZh":{"label":"想说，也开了口，但说到脆弱的地方就想停下来。","reading":"你希望被理解，也可能在真正被看见时感到不安。你靠近了一点，又会想收回一部分，确认自己仍然安全。"}}},{"optionId":"q05-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q05-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Closeness and support","sourceNumber":6}') ON CONFLICT(release_id,question_id) DO NOTHING;
INSERT INTO quiz_release_expectations(release_id,question_id,prompt,options_json,report_config_json) VALUES ('attachment-fixed-v2-2026-10-08','attachment-style-fixed-v2-q06','You have just shared something personal with them. What usually happens afterward?','[{"optionId":"q06-a","label":"I watch their reaction and wonder whether I said too much.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q06-a","tag":"reassurance","title":"After opening up, you wait for a sign of acceptance","reading":"After sharing, your attention can move toward what they now think of you. A clear sign of acceptance may feel necessary before you can trust that opening up has not changed the relationship.","preview":"After sharing, your attention can move toward what they now think of you.","reviewZh":{"label":"盯着对方的反应，担心自己是不是说多了。","reading":"分享过后，你的注意力容易转到对方怎么看你。你可能需要一个明确的接纳信号，才敢相信这次表达没有让关系变差。"}}},{"optionId":"q06-b","label":"I change the subject and keep the next conversation lighter.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q06-b","tag":"self-reliance","title":"You close up the part you just opened","reading":"When a conversation touches something vulnerable, you tend to make it lighter again. Saying less can restore your sense of control over how close the other person gets.","preview":"When a conversation touches something vulnerable, you tend to make it lighter again.","reviewZh":{"label":"换个话题，下一次也尽量少谈这些。","reading":"一旦话题触及自己的脆弱，你会倾向于把交流重新变轻。少说一点，能让你重新掌握彼此靠近的程度。"}}},{"optionId":"q06-c","label":"I feel a little exposed, but let their response unfold.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q06-c","tag":"closeness","title":"You can let your words stay in the relationship","reading":"You can tolerate some discomfort after sharing without immediately taking it back. Their response matters, but it does not instantly decide whether you were allowed to say it.","preview":"You can tolerate some discomfort after sharing without immediately taking it back.","reviewZh":{"label":"有一点不自在，但愿意听听对方怎么回应。","reading":"你可以容纳分享之后的短暂不自在，而不急着撤回表达。对方的回应会参与判断，但不会立刻决定你能不能说这些。"}}},{"optionId":"q06-d","label":"I feel closer briefly, then regret sharing and want to take it back.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q06-d","tag":"push-pull","title":"A moment of closeness is followed by an urge to retreat","reading":"The relief of closeness and the feeling of exposure may arrive together. Soon after letting them in, you may start wondering whether you gave away too much.","preview":"The relief of closeness and the feeling of exposure may arrive together.","reviewZh":{"label":"刚觉得更亲近，很快又后悔，想把刚才的话收回去。","reading":"亲近带来的轻松和暴露感可能同时存在。你刚允许对方靠近，就又开始担心自己是不是交出去太多。"}}},{"optionId":"q06-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q06-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Closeness and support","sourceNumber":7}') ON CONFLICT(release_id,question_id) DO NOTHING;
INSERT INTO quiz_release_expectations(release_id,question_id,prompt,options_json,report_config_json) VALUES ('attachment-fixed-v2-2026-10-08','attachment-style-fixed-v2-q07','When you begin talking seriously about a future together, which thought feels most familiar?','[{"optionId":"q07-a","label":"I keep wondering whether they are as serious about this as I am.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q07-a","tag":"reassurance","title":"You want to know you are not the only one imagining a future","reading":"Talking about the future increases your need to know the investment is mutual. One statement may not settle it; you may keep looking for signs that they mean it as much as you do.","preview":"Talking about the future increases your need to know the investment is mutual.","reviewZh":{"label":"反复想：对方是不是和我一样认真？","reading":"谈未来会让你更想确认投入是否对等。你可能难以只听一次表态，而会继续寻找对方同样认真的证据。"}}},{"optionId":"q07-b","label":"I worry there will be too many expectations and too little room for myself.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q07-b","tag":"distance","title":"You wonder how much room commitment will leave you","reading":"You first notice the responsibilities and limits that commitment might bring. As the relationship becomes more defined, you may need to know that your choices and personal space still belong to you.","preview":"You first notice the responsibilities and limits that commitment might bring.","reviewZh":{"label":"担心以后会有太多要求，自己的空间越来越少。","reading":"你会先注意承诺可能带来的责任和限制。关系变得更确定时，你可能更需要确认自己仍有选择和独处的空间。"}}},{"optionId":"q07-c","label":"I want to understand whether our expectations and pace fit.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q07-c","tag":"clarity","title":"You want a future you have actually talked through","reading":"You care about the future and want to discuss it in concrete terms. Commitment involves understanding each other, rather than only getting an immediate yes.","preview":"You care about the future and want to discuss it in concrete terms.","reviewZh":{"label":"想了解双方的期待和节奏能不能合得来。","reading":"你重视未来，也愿意通过具体讨论了解彼此。承诺需要双方看清和商量，而不只是立刻得到一个肯定答案。"}}},{"optionId":"q07-d","label":"I want the commitment, but start backing away when they seriously agree.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q07-d","tag":"push-pull","title":"You want commitment and hesitate when it becomes real","reading":"You want the relationship to become certain, and can become watchful when that certainty feels real. Wanting it and pulling away can make your own decision feel confusing.","preview":"You want the relationship to become certain, and can become watchful when that certainty feels real.","reviewZh":{"label":"很想确定下来，但对方认真答应时，我又想往后退。","reading":"你渴望确定关系，也可能在承诺变得真实时警觉。期待和退缩并存，会让你对自己的决定也感到困惑。"}}},{"optionId":"q07-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q07-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Closeness and support","sourceNumber":8}') ON CONFLICT(release_id,question_id) DO NOTHING;
INSERT INTO quiz_release_expectations(release_id,question_id,prompt,options_json,report_config_json) VALUES ('attachment-fixed-v2-2026-10-08','attachment-style-fixed-v2-q08','A disagreement is becoming more heated. What is your usual first move?','[{"optionId":"q08-a","label":"I keep talking and asking questions because leaving it unresolved feels worse.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q08-a","tag":"pursuit","title":"Leaving it unresolved feels harder than continuing","reading":"An unresolved issue can make it hard to settle. Trying to restore the connection immediately may keep the conversation going beyond the point when either person can take much in.","preview":"An unresolved issue can make it hard to settle.","reviewZh":{"label":"继续追问、继续说，没说清楚就很难停下来。","reading":"悬着的问题会让你很难安心。你可能想通过当场谈清楚，尽快恢复联系，却忽略了双方此时已经很难听进去。"}}},{"optionId":"q08-b","label":"I go quiet or leave before saying much about what I feel.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q08-b","tag":"withdrawal","title":"Under pressure, you first take yourself out of the conversation","reading":"As tension rises, you reduce contact to get out of the pressure. What that pause means for the relationship also depends on whether you come back to explain and reconnect afterward.","preview":"As tension rises, you reduce contact to get out of the pressure.","reviewZh":{"label":"变得沉默，或者先离开，很少说自己的感受。","reading":"紧张上来时，你会先减少交流，让自己从压力里退出来。这个动作是否伤害关系，还要看之后有没有回来说明和沟通。"}}},{"optionId":"q08-c","label":"I ask for a pause and say when I can return to the conversation.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q08-c","tag":"repair","title":"You make room to cool down and still plan to return","reading":"You give your feelings room to settle while making it clear that the conversation is not being abandoned. The pause and the return are connected in your response.","preview":"You give your feelings room to settle while making it clear that the conversation is not being abandoned.","reviewZh":{"label":"提出暂停，也说明什么时候可以回来继续谈。","reading":"你会给情绪留出缓冲，同时让对方知道对话没有被放弃。暂停和恢复联系，在你的做法里是连在一起的。"}}},{"optionId":"q08-d","label":"I want them close, then tell them to go away when my feelings get stronger.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q08-d","tag":"push-pull","title":"The need for care can come out sounding like rejection","reading":"You may want comfort and push it away when your feelings intensify. The distance you ask for can end up being the opposite of the contact you hoped to receive.","preview":"You may want comfort and push it away when your feelings intensify.","reviewZh":{"label":"想让对方靠近，一激动又说出让对方走开的话。","reading":"你需要安慰，也可能在情绪变强时推开对方。说出口的距离，可能和你当时想获得的联系相反。"}}},{"optionId":"q08-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q08-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Conflict and repair","sourceNumber":9}') ON CONFLICT(release_id,question_id) DO NOTHING;
INSERT INTO quiz_release_expectations(release_id,question_id,prompt,options_json,report_config_json) VALUES ('attachment-fixed-v2-2026-10-08','attachment-style-fixed-v2-q09','They tell you that something you did hurt them. What comes up first?','[{"optionId":"q09-a","label":"I fear they will pull away and rush to check whether we are okay.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q09-a","tag":"pursuit","title":"You worry about losing the connection before understanding the hurt","reading":"Hearing that they are hurt may immediately raise the possibility of losing them. Getting reassurance that the relationship is okay can take priority over understanding what happened.","preview":"Hearing that they are hurt may immediately raise the possibility of losing them.","reviewZh":{"label":"怕对方因此疏远，急着确认我们还好不好。","reading":"听到对方受伤，你可能立刻担心关系会不会失去。你会先争取“我们还好”的确认，具体发生了什么反而容易被挤到后面。"}}},{"optionId":"q09-b","label":"I want to explain the facts and avoid a long conversation about feelings.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q09-b","tag":"withdrawal","title":"You can explain the facts and still leave the feelings outside","reading":"Explaining what happened is a familiar way to handle a problem. Talking about feelings can be less comfortable, and they may leave the conversation feeling that their hurt was not heard.","preview":"Explaining what happened is a familiar way to handle a problem.","reviewZh":{"label":"想把事情解释清楚，但不太想继续谈感受。","reading":"你更习惯通过说明事实处理问题。感受的讨论会让你不自在，却也可能让对方觉得自己的难过没有被听见。"}}},{"optionId":"q09-c","label":"I feel defensive, but want to hear what hurt them.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q09-c","tag":"repair","title":"You stay open to understanding while feeling uncomfortable","reading":"You notice your defensiveness and remain willing to understand their experience. Listening does not mean accepting every accusation; it leaves room to understand and repair.","preview":"You notice your defensiveness and remain willing to understand their experience.","reviewZh":{"label":"虽然有些防御，还是想先听清楚哪里伤到了对方。","reading":"你能注意到自己的防御，也愿意理解对方的体验。听进去并不等于立刻认同所有指责，而是给修复留下入口。"}}},{"optionId":"q09-d","label":"I want to repair it, but also want to hide from their reaction.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q09-d","tag":"push-pull","title":"You want to put it right and hide at the same time","reading":"Repair matters to you, and facing their response can feel difficult. The urge to make things right and the urge to escape may both make a clear conversation harder to begin.","preview":"Repair matters to you, and facing their response can feel difficult.","reviewZh":{"label":"想修复，又怕面对对方的反应，想暂时躲起来。","reading":"你在乎修复，也很怕接下来会发生什么。想补救和想躲开的冲动，可能同时让你难以开始一段清楚的对话。"}}},{"optionId":"q09-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q09-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Conflict and repair","sourceNumber":10}') ON CONFLICT(release_id,question_id) DO NOTHING;
INSERT INTO quiz_release_expectations(release_id,question_id,prompt,options_json,report_config_json) VALUES ('attachment-fixed-v2-2026-10-08','attachment-style-fixed-v2-q10','You agreed to return to a difficult conversation later. What usually happens?','[{"optionId":"q10-a","label":"I contact them before the agreed time because waiting is too hard.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q10-a","tag":"pursuit","title":"An agreed return does not always make waiting easier","reading":"Even with a time agreed, you may keep needing confirmation that the relationship is intact. Reaching out early can interrupt the breathing room you had both planned.","preview":"Even with a time agreed, you may keep needing confirmation that the relationship is intact.","reviewZh":{"label":"还没到约定时间就联系对方，因为等着太难受。","reading":"即使已经约好时间，等待仍可能让你不断想确认关系。你急着恢复联系，也可能打断了原本商量好的缓冲。"}}},{"optionId":"q10-b","label":"Once I feel calmer, I hope we will not need to bring it up again.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q10-b","tag":"withdrawal","title":"You feel calmer, but the issue may still be there","reading":"When the feeling passes, it can seem as though the issue has passed too. They may still be waiting for an explanation, leaving something unresolved between you even while you feel calmer.","preview":"When the feeling passes, it can seem as though the issue has passed too.","reviewZh":{"label":"自己平静下来后，希望这件事就不要再提了。","reading":"情绪过去以后，你容易把“不再难受”当成问题已经过去。对方却可能还在等一次说明，没谈完的事会留在两个人之间。"}}},{"optionId":"q10-c","label":"I return when we agreed, or explain if I need to change the time.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q10-c","tag":"repair","title":"You make the return after a pause actually happen","reading":"You turn the promise to reconnect into something observable. A disagreement need not be solved at once for the other person to know you are still taking it seriously.","preview":"You turn the promise to reconnect into something observable.","reviewZh":{"label":"按约定回来谈；如果需要改时间，会说明。","reading":"你能把暂停之后的承诺落到行动上。分歧不必一次解决，但对方能够知道，这段对话仍然有人在认真对待。"}}},{"optionId":"q10-d","label":"I want to talk, then hesitate when the time comes; afterward I worry we are further apart.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q10-d","tag":"push-pull","title":"You want to reconnect and retreat as the moment arrives","reading":"You want the connection restored and also dread facing the tension again. Pulling back as the conversation approaches can leave you with a new worry about the distance.","preview":"You want the connection restored and also dread facing the tension again.","reviewZh":{"label":"等着重新谈，到了时间又想躲；错过后又担心更疏远。","reading":"你希望关系恢复，却也怕重新面对紧张。临近沟通时的退缩，会让原本想修复的你再次陷入担心。"}}},{"optionId":"q10-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q10-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Conflict and repair","sourceNumber":11}') ON CONFLICT(release_id,question_id) DO NOTHING;
INSERT INTO quiz_release_expectations(release_id,question_id,prompt,options_json,report_config_json) VALUES ('attachment-fixed-v2-2026-10-08','attachment-style-fixed-v2-q11','They want to see you tonight, but you need time to yourself. What do you usually do?','[{"optionId":"q11-a","label":"I consider agreeing because I worry that saying no will disappoint them.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q11-a","tag":"burden","title":"Their disappointment can come before your own need","reading":"When your need might disappoint someone, the relationship can come first. Agreeing once means little on its own; repeatedly overriding yourself can build tiredness and resentment.","preview":"When your need might disappoint someone, the relationship can come first.","reviewZh":{"label":"担心拒绝会让对方失望，想勉强答应。","reading":"当自己的需要可能让对方失望时，你容易先照顾关系。一次答应并不说明什么，但反复勉强自己可能让疲惫和委屈累积。"}}},{"optionId":"q11-b","label":"I find a reason to be unavailable without explaining much.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q11-b","tag":"distance","title":"You protect your space without always explaining it","reading":"You protect your time through distance rather than describing what you need. They may know you are not coming without understanding that you simply need rest.","preview":"You protect your time through distance rather than describing what you need.","reviewZh":{"label":"找个理由不见，尽量不解释自己的感受。","reading":"你会用实际距离保护自己的时间，却不太习惯把需要说出来。对方可能知道你不来，却不知道你只是需要休息。"}}},{"optionId":"q11-c","label":"I say I need the evening and discuss another time if I want to.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q11-c","tag":"boundary","title":"You can make your own plans clear","reading":"You make your own plans clear and leave room for a conversation. This describes how you respond in this situation, rather than proving you always handle every boundary the same way.","preview":"You make your own plans clear and leave room for a conversation.","reviewZh":{"label":"直接说今晚需要独处，愿意见面时再商量时间。","reading":"你会把自己的安排说清楚，也给彼此留出商量的空间。这次选择说明的是这一情境里的表达方式，不代表你在所有场景都如此。"}}},{"optionId":"q11-d","label":"I fear they will stop asking if I say no, but want to cancel after agreeing.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q11-d","tag":"push-pull","title":"You fear losing the invitation and then want to take back your yes","reading":"You want to be wanted, and agreeing to closeness can also feel pressuring. Saying yes to keep the connection, then wanting to withdraw to protect your space, can leave you caught between both needs.","preview":"You want to be wanted, and agreeing to closeness can also feel pressuring.","reviewZh":{"label":"怕拒绝后对方不再约我，答应了又想临时取消。","reading":"你希望被邀请和被需要，也可能在答应靠近后感到压力。为了不失去联系而答应，再为保护空间而撤回，会让你更加为难。"}}},{"optionId":"q11-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q11-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Needs and boundaries","sourceNumber":13}') ON CONFLICT(release_id,question_id) DO NOTHING;
INSERT INTO quiz_release_expectations(release_id,question_id,prompt,options_json,report_config_json) VALUES ('attachment-fixed-v2-2026-10-08','attachment-style-fixed-v2-q12','You wish they would check in more often. What do you usually do?','[{"optionId":"q12-a","label":"Bring it up repeatedly because I still do not feel sure they really want to.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q12-a","tag":"reassurance","title":"You ask for contact and still question whether it is freely wanted","reading":"You express the need, but one answer may not settle it. Repeating the request can reflect uncertainty about whether they want to come toward you on their own.","preview":"You express the need, but one answer may not settle it.","reviewZh":{"label":"反复提起，因为还是不确定对方是不是真的愿意。","reading":"你会表达需要，但一次答复可能很难让你安心。反复提起的背后，可能是你还没有相信对方愿意主动靠近。"}}},{"optionId":"q12-b","label":"Tell myself I should need less and keep it to myself.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q12-b","tag":"self-reliance","title":"You reduce the need before giving it a chance to be heard","reading":"You try to make your own needs smaller so the relationship feels easier. Over time, they may think you are satisfied without knowing that you had hoped for more.","preview":"You try to make your own needs smaller so the relationship feels easier.","reviewZh":{"label":"告诉自己别需要这么多，最后还是不说。","reading":"你会先尝试把自己的需要压小，让关系保持轻松。时间久了，对方可能以为你一直满意，却不知道你也曾期待更多。"}}},{"optionId":"q12-c","label":"Say what I would like and ask what works for them.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q12-c","tag":"clarity","title":"You give your need a chance to receive a real response","reading":"You make an expectation specific enough to discuss. Their response and follow-through can then give you useful information about what is possible between you.","preview":"You make an expectation specific enough to discuss.","reviewZh":{"label":"说清楚我希望怎样联系，也问对方能做到什么。","reading":"你能把期待变成可以讨论的具体安排。对方如何回应和履行，会成为你判断关系的重要信息。"}}},{"optionId":"q12-d","label":"Start to ask, then say never mind because I feel too needy.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q12-d","tag":"push-pull","title":"Your need comes out and is quickly taken back","reading":"You want them to know what you hope for, and feel exposed when they can see it. Taking it back may ease that discomfort while making your real request harder to understand.","preview":"You want them to know what you hope for, and feel exposed when they can see it.","reviewZh":{"label":"刚提出来，就怕显得太需要对方，又说算了。","reading":"你想让对方知道自己的期待，也怕被看见需要太多。把话收回去会暂时减少不自在，却让对方难以理解你真正想要什么。"}}},{"optionId":"q12-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q12-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Needs and boundaries","sourceNumber":14}') ON CONFLICT(release_id,question_id) DO NOTHING;
INSERT INTO quiz_release_expectations(release_id,question_id,prompt,options_json,report_config_json) VALUES ('attachment-fixed-v2-2026-10-08','attachment-style-fixed-v2-q13','The relationship has been steady for several weeks, without obvious conflict or broken promises. What do you notice?','[{"optionId":"q13-a","label":"I still look for reassurance that their warmth has not started to fade.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q13-a","tag":"reassurance","title":"You keep checking even when things are steady","reading":"Even without an obvious change, you may keep checking the relationship. Trying to protect the stability can make it harder to enjoy the stability you already have.","preview":"Even without an obvious change, you may keep checking the relationship.","reviewZh":{"label":"还是会寻找保证，确认对方的热情没有变淡。","reading":"外部变化不明显时，你仍可能主动检查关系。你想维持这份稳定，但不断确认也可能让自己很难真正享受它。"}}},{"optionId":"q13-b","label":"I start wanting less closeness, without a clear reason I can name.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q13-b","tag":"distance","title":"Steady closeness can still make you want to step back","reading":"As closeness continues, some distance can feel like a way to get comfortable again. What matters is whether this retreat repeats, rather than treating every wish for time alone as avoidance.","preview":"As closeness continues, some distance can feel like a way to get comfortable again.","reviewZh":{"label":"开始想减少一些亲密接触，却又说不清具体原因。","reading":"当关系持续靠近，你可能想通过一点距离恢复自在。需要留意的是这种退开是否反复出现，而不是把所有独处都解释成回避。"}}},{"optionId":"q13-c","label":"I enjoy the relationship and keep enjoying the rest of my life.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q13-c","tag":"space","title":"Stability leaves you more room to be yourself","reading":"Stability leaves you more room for the rest of your life. Closeness and independence can exist together without constant checks to keep the relationship in place.","preview":"Stability leaves you more room for the rest of your life.","reviewZh":{"label":"能享受这段关系，也继续过好自己的生活。","reading":"稳定会让你更有余地投入关系之外的生活。亲近和独立可以同时存在，不必靠持续确认维持联系。"}}},{"optionId":"q13-d","label":"I value the calm, but hold back some investment in case I get hurt later.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q13-d","tag":"push-pull","title":"You want to enjoy the calm and prepare for its ending","reading":"You can recognize what is good and still start preparing to lose it. Holding back may feel protective in the moment while limiting how much of that steadiness you let yourself experience.","preview":"You can recognize what is good and still start preparing to lose it.","reviewZh":{"label":"很珍惜这份稳定，却又提前收回投入，怕以后受伤。","reading":"你已经感受到关系的好，也可能开始为失去它做准备。提前收回投入能让你暂时安心，却会限制你体验这段稳定的程度。"}}},{"optionId":"q13-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q13-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Stability and trust","sourceNumber":17}') ON CONFLICT(release_id,question_id) DO NOTHING;
INSERT INTO quiz_release_expectations(release_id,question_id,prompt,options_json,report_config_json) VALUES ('attachment-fixed-v2-2026-10-08','attachment-style-fixed-v2-q14','After a conversation in which they genuinely address your worries, what usually happens next?','[{"optionId":"q14-a","label":"I feel better briefly, then a small change makes me seek reassurance again.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q14-a","tag":"reassurance","title":"You receive reassurance and struggle to keep it with you","reading":"Their response can ease the immediate worry without making the reassurance last. The next small change may send you back to checking whether you still matter.","preview":"Their response can ease the immediate worry without making the reassurance last.","reviewZh":{"label":"短暂安心，之后一点变化又让我想重新确认。","reading":"这次回应可以缓解眼前的不安，但安心不容易持续。下一次小变化出现时，你可能又回到重新确认自己是否重要的过程。"}}},{"optionId":"q14-b","label":"I still feel more comfortable handling my feelings myself than relying on the conversation.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q14-b","tag":"self-reliance","title":"Handling it yourself still feels more familiar than accepting comfort","reading":"They have responded, and your familiar way of settling is still to work through it alone. Letting someone else take part in comforting you may need more getting used to.","preview":"They have responded, and your familiar way of settling is still to work through it alone.","reviewZh":{"label":"不太习惯靠这样的谈话安心，还是想自己处理感受。","reading":"对方回应了你，你仍可能更信任自己消化感受的方式。让另一个人参与安慰和支持，对你来说需要更多适应。"}}},{"optionId":"q14-c","label":"I can carry the reassurance with me unless something new happens.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q14-c","tag":"trust","title":"One reliable response can become part of your trust","reading":"You can let a reliable response inform what happens next. Without new information, you do not need to keep proving the relationship is safe all over again.","preview":"You can let a reliable response inform what happens next.","reviewZh":{"label":"能把这次回应放在心里，除非出现新的问题。","reading":"你能够把一次可靠的回应带进之后的相处。没有新的情况时，不必不断重新证明关系是否安全。"}}},{"optionId":"q14-d","label":"I want to believe them, but share less and keep some distance just in case.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q14-d","tag":"push-pull","title":"You want to trust and keep an exit available","reading":"Their response makes you want to trust, and also reminds you how much you could depend on the relationship. Keeping a little distance lets you believe without feeling completely exposed.","preview":"Their response makes you want to trust, and also reminds you how much you could depend on the relationship.","reviewZh":{"label":"很想相信，但又开始少说少靠近，给自己留退路。","reading":"回应让你想重新信任，也让你意识到自己可能更依赖这段关系。你会在相信的同时保留距离，避免把自己完全交出去。"}}},{"optionId":"q14-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q14-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Stability and trust","sourceNumber":20}') ON CONFLICT(release_id,question_id) DO NOTHING;
INSERT INTO quiz_release_expectations(release_id,question_id,prompt,options_json,report_config_json) VALUES ('attachment-fixed-v2-2026-10-08','attachment-style-fixed-v2-q15','Think of a current or recent important romantic relationship. When you try to discuss a disagreement, what does the other person usually do?','[{"optionId":"q15-a","label":"Talk, or agree on a pause and actually return to the conversation.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q15-a","tag":"partner_returns","title":"A pause can still lead back to connection","reading":"You describe an interaction in which a pause can lead back to a conversation. Returning gives the issue a chance to be addressed. If waiting still feels difficult, that feeling matters too; this particular pause does not by itself mean you are being abandoned.","preview":"You describe an interaction in which a pause can lead back to a conversation.","reviewZh":{"label":"愿意谈；需要暂停时会约好时间，之后也会回来。","reading":"你描述的是一种能够暂停、也能够继续的互动。对方愿意回来，会让问题有机会真正被处理。如果等待期间你仍很难安心，可以结合自己的反应理解，而不必把这次暂停直接当成疏远。"}}},{"optionId":"q15-b","label":"Stop replying or leave, and rarely return to discuss it.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q15-b","tag":"partner_disappears","title":"Waiting without an ending can be what wears you down","reading":"You describe an issue that often has no follow-up. The longer you wait, the more you may question, guess, or stop trying to speak. The cost can accumulate quietly: things look normal again while the hurt that started the conversation remains unresolved.","preview":"You describe an issue that often has no follow-up.","reviewZh":{"label":"不回复或离开，之后也很少再回来谈。","reading":"你面对的是问题经常没有下文的互动。等待越久，你越可能追问、猜测，或者放弃表达。这里需要看清的代价是：关系表面恢复了，未解决的委屈却可能继续累积。"}}},{"optionId":"q15-c","label":"Push for an immediate answer and struggle to allow a pause.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q15-c","tag":"partner_presses","title":"When a pause is not allowed, closeness can feel like pressure","reading":"An immediate demand for answers can leave little room to settle. If you retreat under pressure, the more they push, the harder it may become to speak. Repeated often, a conversation can start feeling like something to escape rather than something you can return to.","preview":"An immediate demand for answers can leave little room to settle.","reviewZh":{"label":"要求马上说清楚，很难接受我需要暂停。","reading":"对方想立刻得到回应，可能让你觉得没有缓冲的空间。你越退，对方越急；对方越急，你越难开口。如果这种互动反复出现，沟通容易变成互相催促和躲避。"}}},{"optionId":"q15-d","label":"It varies: sometimes they engage, and sometimes they suddenly shut me out.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q15-d","tag":"partner_inconsistent","title":"Unpredictable responses make it hard to settle","reading":"You cannot easily predict how the next disagreement will be received. One good conversation may not reassure you because the next one could go very differently. That uncertainty can use up energy you would otherwise put into deciding what you need and whether the relationship works for you.","preview":"You cannot easily predict how the next disagreement will be received.","reviewZh":{"label":"很不固定；有时愿意谈，有时突然不理我。","reading":"你很难预料下一次分歧会被怎样回应。于是，一次好的谈话未必能让你放心，因为下一次仍可能完全不同。这种不确定会消耗你判断关系的精力。"}}},{"optionId":"q15-skip","label":"I do not remember / Not applicable / Prefer not to answer","microcopy":"","meaning":"","projection":"","fixed":{"id":"q15-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不记得／不适用／暂不想回答","reading":"不补写这段经历，不使用依恋类型猜测答案。报告会明确这部分信息不足，并使用其他已经回答的线索。"}}}]','{"version":"attachment-fixed-v2","kind":"relationship","domain":"Your relationship","sourceNumber":4}') ON CONFLICT(release_id,question_id) DO NOTHING;
INSERT INTO quiz_release_expectations(release_id,question_id,prompt,options_json,report_config_json) VALUES ('attachment-fixed-v2-2026-10-08','attachment-style-fixed-v2-q16','In that same relationship, when you clearly ask for something you need, how does the other person usually respond?','[{"optionId":"q16-a","label":"Discuss what is possible and usually follow through.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q16-a","tag":"needs_followthrough","title":"Care becomes easier to trust when something happens afterward","reading":"There is both a conversation and action afterward. This can gradually strengthen trust: you do not have to rely on a promise alone to judge whether you are being considered. Their actual follow-through becomes information you can carry into the next uncertain moment.","preview":"There is both a conversation and action afterward.","reviewZh":{"label":"一起商量能做到什么，之后通常会履行。","reading":"对方的回应有商量，也有后续行动。这样的经历可以慢慢增加信任：你不用只靠一句承诺判断自己是否被在意。你可以把这些实际行动，作为判断关系是否可靠的一部分。"}}},{"optionId":"q16-b","label":"Agree warmly in the moment, but often do not follow through.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q16-b","tag":"needs_empty_promises","title":"A warm promise can keep you waiting much longer","reading":"A warm yes can renew your hope, and repeated non-delivery can disappoint you again. You may keep waiting because the promise felt sincere, while the original problem does not change. Brief hope followed by another letdown can make it increasingly difficult to decide how long to keep waiting.","preview":"A warm yes can renew your hope, and repeated non-delivery can disappoint you again.","reviewZh":{"label":"当时答应得很好，之后却常常没有做到。","reading":"短暂的答应会让你重新有期待，反复落空又让你失望。你可能因为一次温暖的回应继续等，却发现相同的问题始终没有改变。短暂的希望与反复的落空，可能让你越来越难判断自己还要等多久。"}}},{"optionId":"q16-c","label":"Dismiss the request or say I am asking for too much.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q16-c","tag":"needs_dismissed","title":"Do your needs always have to earn permission first?","reading":"When needs are repeatedly dismissed, you may begin to doubt whether you should ask at all, or become more urgent about being heard. The cost can be spending more and more energy proving that your request is reasonable, with very little actual response to the need itself.","preview":"When needs are repeatedly dismissed, you may begin to doubt whether you should ask at all, or become more urgent about being heard.","reviewZh":{"label":"觉得我要求太多，或者把这个需要直接带过去。","reading":"当需要经常被否定，你可能开始怀疑自己是不是不该开口，也可能越说越急。关系的代价可能在于：你越来越忙着证明需要合理，却很少真正得到回应。"}}},{"optionId":"q16-d","label":"Need time, then return with a clear answer or another workable option.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q16-d","tag":"needs_clear_delay","title":"A later answer with follow-through is different from a broken promise","reading":"The response is not immediate, but there is consideration and an answer. This is different from a delay with no follow-up. Even if you do not get everything you hoped for, a clear explanation gives you something real to consider instead of leaving you to guess indefinitely.","preview":"The response is not immediate, but there is consideration and an answer.","reviewZh":{"label":"需要一些时间，但之后会给出明确答复或替代办法。","reading":"对方没有立刻满足，却愿意认真考虑并给出交代。这更接近有边界的回应。等待里有明确的交代，你就有更多信息判断对方是否认真对待。"}}},{"optionId":"q16-skip","label":"I do not remember / Not applicable / Prefer not to answer","microcopy":"","meaning":"","projection":"","fixed":{"id":"q16-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不记得／不适用／暂不想回答","reading":"不补写这段经历，不使用依恋类型猜测答案。报告会明确这部分信息不足，并使用其他已经回答的线索。"}}}]','{"version":"attachment-fixed-v2","kind":"relationship","domain":"Your relationship","sourceNumber":12}') ON CONFLICT(release_id,question_id) DO NOTHING;
INSERT INTO quiz_release_expectations(release_id,question_id,prompt,options_json,report_config_json) VALUES ('attachment-fixed-v2-2026-10-08','attachment-style-fixed-v2-q17','Growing up, when something upset or frightened you, what usually happened when you asked your main caregiver for help?','[{"optionId":"q17-a","label":"Someone usually listened and tried to give me the support I needed.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q17-a","tag":"family_help_available","title":"You have known what it is like for a need to receive a response","reading":"You remember someone being willing to understand your feelings and take part in helping. Those experiences may have made asking feel possible. If relying on others is difficult now, later experiences may also matter. Having received support and finding it hard to feel safe today can both be part of your story.","preview":"You remember someone being willing to understand your feelings and take part in helping.","reviewZh":{"label":"通常有人认真听，也会尽量给我需要的支持。","reading":"你记得的回应里，有人愿意参与解决困难，也愿意了解你的感受。这样的经历可能让你更容易相信，需要可以被说出来。如果你现在仍很难求助，也可能与后来的经历有关；有过支持和现在不易放心，可以同时存在。"}}},{"optionId":"q17-b","label":"Sometimes they helped and sometimes they did not; it was hard to predict.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q17-b","tag":"family_help_unpredictable","title":"You may have learned to check their mood before you asked","reading":"When a similar need received different responses, you may have learned to observe before asking. Later, a small change in someone close to you can quickly draw your attention: is this still a moment when I can turn toward them? The skill of noticing can remain active even when you wish you could simply relax.","preview":"When a similar need received different responses, you may have learned to observe before asking.","reviewZh":{"label":"有时会帮助我，有时不理我，很难提前知道。","reading":"当同样的需要得到不同的回应，你可能逐渐学会先观察，再决定要不要开口。后来，亲近的人一点语气变化，也可能让你马上留意：现在还能不能向对方靠近？"}}},{"optionId":"q17-c","label":"Asking rarely brought the support I needed, so I usually handled it myself.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q17-c","tag":"family_help_unavailable","title":"When did relying on yourself start to feel like the only real option?","reading":"If you repeatedly asked a parent or caregiver for help and found that they could not provide the support you needed, you may have reached a conclusion: asking does not change much; in the end, I have to rely on myself. You learned to work through hurt alone and solve difficulties yourself. Later, even in a close relationship, depending on someone may rarely feel like an available choice.","preview":"If you repeatedly asked a parent or caregiver for help and found that they could not provide the support you needed, you may have reached a conclusion: asking does not change much; in the end, I have to rely on myself.","reviewZh":{"label":"找他们也很难得到需要的帮助，最后通常还是自己处理。","reading":"如果小时候，你多次向父母或主要照顾者寻求帮助，却发现他们也无法给你需要的支持，你可能慢慢形成一个想法：说了也没用，最后还是得靠自己。后来，难过的时候，你学会自己消化；遇到困难，你习惯自己解决。即使进入亲密关系，也很少把“依靠对方”当作一个选择。"}}},{"optionId":"q17-d","label":"Asking sometimes brought criticism and left me feeling worse.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q17-d","tag":"family_help_backfires","title":"You want help and worry about what happens after you ask","reading":"If asking could make things harder, you may have started considering the consequences before speaking. The wish for support remained, but the question of whether asking would make things worse could stop it. Later, wanting to come closer to someone may also bring an immediate urge to protect what they can see.","preview":"If asking could make things harder, you may have started considering the consequences before speaking.","reviewZh":{"label":"求助有时会换来责备，让我比开口前更难受。","reading":"如果求助可能带来更多责备，你可能逐渐在开口前先考虑后果。需要支持的感觉仍然存在，却会被“说出来会不会更糟”挡住。后来，你也可能在想靠近一个人时，同时开始保护自己。"}}},{"optionId":"q17-skip","label":"I do not remember / Not applicable / Prefer not to answer","microcopy":"","meaning":"","projection":"","fixed":{"id":"q17-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不记得／不适用／暂不想回答","reading":"不补写这段经历，不使用依恋类型猜测答案。报告会明确这部分信息不足，并使用其他已经回答的线索。"}}}]','{"version":"attachment-fixed-v2","kind":"family","domain":"Family and experience","sourceNumber":15}') ON CONFLICT(release_id,question_id) DO NOTHING;
INSERT INTO quiz_release_expectations(release_id,question_id,prompt,options_json,report_config_json) VALUES ('attachment-fixed-v2-2026-10-08','attachment-style-fixed-v2-q18','Growing up, what felt most familiar when you wanted attention, company, or help?','[{"optionId":"q18-a","label":"I could usually ask directly and get a clear response.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q18-a","tag":"family_direct","title":"There were times when your needs could be said directly","reading":"You remember asking being followed by a response you could understand. Not every request had to be granted for you to know where you stood. Even if you do not always feel settled now, those experiences of a clear response remain part of what you know relationships can offer.","preview":"You remember asking being followed by a response you could understand.","reviewZh":{"label":"通常可以直接说，对方也会给我清楚的回应。","reading":"你比较熟悉直接表达后的清楚回应。即使对方不能每次满足，也不必一直靠猜来理解。即使现在不总能安心，这些清楚回应的经历，也仍然是你对关系的经验的一部分。"}}},{"optionId":"q18-b","label":"I checked the adult''s mood before deciding whether to ask.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q18-b","tag":"family_mood","title":"You check how they are before making room for yourself","reading":"You may have practiced reading other people very early. In close relationships, the sequence can still feel familiar: work out whether they want to listen, then decide whether your need can appear. Over time, managing their mood may come more naturally than describing what you need yourself.","preview":"You may have practiced reading other people very early.","reviewZh":{"label":"先看大人的心情，再决定要不要说。","reading":"你可能很早就练习观察别人的状态。这个习惯在亲密关系里仍可能很熟悉：先判断对方愿不愿意听，再决定自己的需要该不该出现。久了，照顾对方的情绪可能比表达自己更自然。"}}},{"optionId":"q18-c","label":"I was praised for being independent and not asking for much.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q18-c","tag":"family_independence_rewarded","title":"When did needing less become part of being good?","reading":"If being easy or grown-up often meant needing little, carrying things yourself may have become a way to keep relationships comfortable. Later, others may see independence without seeing the effort it takes. They may not realize that you also become tired and sometimes wish someone would take care of you.","preview":"If being easy or grown-up often meant needing little, carrying things yourself may have become a way to keep relationships comfortable.","reviewZh":{"label":"少提要求、自己处理时，更容易被夸懂事。","reading":"如果“懂事”常常意味着少麻烦别人，你可能逐渐把自己承担当成维持好关系的方式。后来，别人看到的是你很独立，却不一定知道你也会累，也希望被照顾。"}}},{"optionId":"q18-d","label":"I found it easier to get attention after doing well or being helpful.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q18-d","tag":"family_earned_attention","title":"Do you feel you have to offer something before you can need something?","reading":"If attention was closely linked to achievement or usefulness, doing more may have become a familiar way to feel important. In a relationship, you might keep giving without finding out whether your needs also matter when you are not earning your place through effort.","preview":"If attention was closely linked to achievement or usefulness, doing more may have become a familiar way to feel important.","reviewZh":{"label":"表现好、做出成绩或帮了忙，更容易得到关注。","reading":"如果被关注常和表现联系在一起，你可能更容易通过付出证明自己的重要。进入关系后，这可能表现为不断做得更多，却很少停下来确认：不付出的时候，我的需要是否也值得被认真对待？"}}},{"optionId":"q18-skip","label":"I do not remember / Not applicable / Prefer not to answer","microcopy":"","meaning":"","projection":"","fixed":{"id":"q18-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不记得／不适用／暂不想回答","reading":"不补写这段经历，不使用依恋类型猜测答案。报告会明确这部分信息不足，并使用其他已经回答的线索。"}}}]','{"version":"attachment-fixed-v2","kind":"family","domain":"Family and experience","sourceNumber":16}') ON CONFLICT(release_id,question_id) DO NOTHING;
INSERT INTO quiz_release_expectations(release_id,question_id,prompt,options_json,report_config_json) VALUES ('attachment-fixed-v2-2026-10-08','attachment-style-fixed-v2-q19','Growing up, what usually happened after a disagreement at home?','[{"optionId":"q19-a","label":"We spoke again, and there was a chance to discuss what happened.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q19-a","tag":"family_repair","title":"A disagreement could still lead back to being heard","reading":"You may have known that conflict could be followed by renewed contact and a conversation. That gives you a reference for what repair can look like. It does not mean that disagreements never frighten or upset you; it means an argument did not always have to be the end of being heard.","preview":"You may have known that conflict could be followed by renewed contact and a conversation.","reviewZh":{"label":"之后会重新说话，问题也有机会被谈清楚。","reading":"你可能较早接触过一种经验：有矛盾，关系仍然可以继续沟通。这样的经历能为之后的修复提供参照，但不代表你每次冲突都不会害怕或难受。"}}},{"optionId":"q19-b","label":"Someone stopped speaking for a long time, and I did not know when it would end.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q19-b","tag":"family_silent","title":"Silence without a clear ending can carry extra weight","reading":"When silence had no clear ending, waiting may have become especially uncomfortable. Later, a pause in contact can make the return feel urgent. You may also recognize silence as a familiar way to respond yourself. What matters is which of those reactions actually appears in your answers today.","preview":"When silence had no clear ending, waiting may have become especially uncomfortable.","reviewZh":{"label":"有人长时间不说话，我不知道什么时候才会结束。","reading":"如果沉默何时结束一直不清楚，等待可能成为一种很难受的经验。后来，伴侣暂时没有回应时，你可能会特别在意何时能恢复联系；也可能把沉默当成自己熟悉的应对方式。"}}},{"optionId":"q19-c","label":"Things went back to normal, but we rarely discussed what had happened.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q19-c","tag":"family_unspoken","title":"Where did the unspoken hurt go after everyone calmed down?","reading":"Calm returning did not necessarily mean that hurt had been understood. You may have become familiar with letting things pass without talking them through. Later, no longer arguing can feel like having repaired the relationship, even when one person still carries something that was never heard.","preview":"Calm returning did not necessarily mean that hurt had been understood.","reviewZh":{"label":"过一会儿就像没事一样，但很少再谈发生了什么。","reading":"家里恢复平静，并不一定意味着委屈被说清。你可能因此熟悉“过去就算了”的相处方式。进入关系后，有时会把不再争执当成已经和好，却留下没有被听见的部分。"}}},{"optionId":"q19-d","label":"I often calmed people down or gave in so we could get along again.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q19-d","tag":"family_peacemaker","title":"Are you still the one responsible for making everyone feel okay?","reading":"If you often helped restore the atmosphere, looking after the relationship before your own feelings may feel natural. Later, you may become the person who repeatedly initiates repair. The hidden cost is how little room remains to notice whether the other person is sharing that responsibility.","preview":"If you often helped restore the atmosphere, looking after the relationship before your own feelings may feel natural.","reviewZh":{"label":"我经常先安抚大家、主动让步，让气氛恢复。","reading":"如果你常常承担缓和气氛的角色，你可能很熟悉先顾全关系，再处理自己的感受。长大后，这种习惯可能让你一次次主动修复，却很少确认对方有没有一起承担。"}}},{"optionId":"q19-skip","label":"I do not remember / Not applicable / Prefer not to answer","microcopy":"","meaning":"","projection":"","fixed":{"id":"q19-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不记得／不适用／暂不想回答","reading":"不补写这段经历，不使用依恋类型猜测答案。报告会明确这部分信息不足，并使用其他已经回答的线索。"}}}]','{"version":"attachment-fixed-v2","kind":"family","domain":"Family and experience","sourceNumber":19}') ON CONFLICT(release_id,question_id) DO NOTHING;
INSERT INTO quiz_release_expectations(release_id,question_id,prompt,options_json,report_config_json) VALUES ('attachment-fixed-v2-2026-10-08','attachment-style-fixed-v2-q20','Which past romantic relationship experience most changed how you respond to closeness now?','[{"optionId":"q20-a","label":"A relationship suddenly became distant or ended without much explanation.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q20-a","tag":"history_abrupt","title":"An unexplained ending can change the way you wait","reading":"Losing contact without much explanation can make later changes more noticeable. You might look for distance sooner, or invest less before it can hurt. Experiences after childhood can also change how you understand closeness; you do not need to fit every current reaction into a single early family story.","preview":"Losing contact without much explanation can make later changes more noticeable.","reviewZh":{"label":"一段关系突然变冷或结束，对方没有给多少解释。","reading":"突然失去联系或缺少交代，可能让之后的变化变得格外显眼。你可能会更快察觉疏远，也可能提前减少投入。后来发生的事，也可能改变了你现在理解亲近的方式。"}}},{"optionId":"q20-b","label":"Promises were repeatedly made and not kept.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q20-b","tag":"history_promises","title":"A promise may no longer be enough to let you hope","reading":"Repeated broken promises can make words less reassuring. Even when someone means what they say now, you may want more confirmation, watch for action, or hold back your expectations. It can take observable follow-through before a promise begins to feel like something you can rely on.","preview":"Repeated broken promises can make words less reassuring.","reviewZh":{"label":"对方经常许下承诺，却一次次没有做到。","reading":"反复失信可能让一句承诺越来越难让你安心。后来，即使有人认真答应，你也可能更想确认、继续观察，或者先不抱希望。一句答应能不能成为信任，可能要经过更多实际行动来确认。"}}},{"optionId":"q20-c","label":"My privacy, boundaries, or vulnerability were not respected.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q20-c","tag":"history_boundaries","title":"Your caution may be connected to trust that was not respected","reading":"If trust you offered was not respected, saying less and keeping distance may have become ways to protect yourself. You may pay closer attention to how someone handles your limits and whether what you share is treated carefully. This experience can matter without needing to assume additional details about what happened.","preview":"If trust you offered was not respected, saying less and keeping distance may have become ways to protect yourself.","reviewZh":{"label":"我的隐私、界限，或说过的脆弱没有被尊重。","reading":"如果你曾经交出去的信任没有被尊重，之后少说一点、留一点距离，可能成了保护自己的方式。你会更加在意对方怎样对待你的界限，以及说出口的感受能不能被尊重。"}}},{"optionId":"q20-d","label":"Consistent care gradually helped me feel safer being close.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q20-d","tag":"history_reliable","title":"A later relationship may have helped you learn to feel safer","reading":"You remember a later relationship offering reliable responses over time. That may have helped you become more willing to speak and depend on someone, even while some older habits remained. You can still have moments of doubt and also have become more willing to try trusting than you were before.","preview":"You remember a later relationship offering reliable responses over time.","reviewZh":{"label":"有人长期可靠地回应我，让我逐渐敢于亲近。","reading":"你记得的后来经历里，有持续的可靠回应。这样的相处可能让你慢慢愿意表达和依靠，即使有些旧习惯还在。你可以仍然有不安，也已经比过去更愿意尝试信任。"}}},{"optionId":"q20-none","label":"No experience stands out as changing this for me.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q20-none","tag":"history_none","title":"No specific turning point was identified","reading":"You did not identify a particular turning point. This does not mean that nothing difficult ever happened, and the report will not invent an experience to fill the gap.","preview":"You did not identify a particular turning point.","reviewZh":{"label":"没有明显改变我的经历","reading":"没有选出明确的后续经历，不等于从未遇到困难。报告不会为这一章编造转折，也不会把缺少经历当成任何一种依恋类型。"}}},{"optionId":"q20-skip","label":"I do not remember / Not applicable / Prefer not to answer","microcopy":"","meaning":"","projection":"","fixed":{"id":"q20-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不记得／不适用／暂不想回答","reading":"不补写这段经历，不使用依恋类型猜测答案。报告会明确这部分信息不足，并使用其他已经回答的线索。"}}}]','{"version":"attachment-fixed-v2","kind":"history","domain":"Family and experience","sourceNumber":18}') ON CONFLICT(release_id,question_id) DO NOTHING;
INSERT INTO quiz_report_templates(version,revision,content_json) VALUES ('attachment-fixed-v2',1,'{"version":"attachment-fixed-v2","revision":1,"profiles":{"anxious":{"label":"Anxious attachment","headline":"You care deeply. Feeling sure is the harder part.","summary":"Small changes in contact can take up a lot of space in your mind. You may want to talk, check, and make sure you still matter. Reassurance can help in the moment, while the next unanswered message brings the question back.","traits":["You notice changes in warmth or contact quickly.","Unfinished conversations can be hard to leave alone.","You may seek reassurance more than once.","A response can settle you briefly without making the worry disappear.","You can put the connection ahead of your own rest or limits."],"risks":[{"id":"anxious-unfinished","title":"When you keep reaching and the conversation never comes back","preview":"A disagreement can turn into hours of waiting for proof that you still matter.","paragraphs":["A pause with a clear return can give both people breathing room. A repeated pattern of disappearing without returning leaves a different task on your shoulders: you are left to work out whether there is still a conversation, or even a relationship, to return to.","If your familiar response is to keep asking, the uncertainty can make each message feel necessary. You may explain more, soften your words, or apologize for having brought it up. The original issue can disappear beneath the effort to restore contact.","The cost is not simply that you sent several messages. It is that having a need begins to feel dangerous, while getting any reply starts to feel like a successful repair. Contact has resumed, but what hurt you may still be untouched."]},{"id":"anxious-warmth","title":"Why a little warmth can keep you waiting","preview":"Relief can feel so good that the repeated disappointment becomes harder to evaluate.","paragraphs":["After a period of distance, one affectionate conversation can feel disproportionately important. It restores something you have been trying to reach, and it may make the relationship feel promising again before much has changed in practice.","This can become especially tiring when agreements are warm but rarely followed through. You may keep measuring the relationship by the best return of affection, rather than by the pattern you live with between those moments.","Warmth is meaningful. Its return alone does not tell you whether the underlying problem is changing. A relationship can contain real affection and still leave your needs repeatedly waiting."]},{"id":"anxious-repair","title":"When keeping the peace becomes your job","preview":"You may be repairing the connection so quickly that your own hurt never gets a turn.","paragraphs":["You might be the person who reaches out first, adjusts the wording, and looks for a way to make things feel okay. That effort can preserve a conversation. Repeatedly carrying it alone can also teach the relationship that your discomfort will eventually make you do the repair work.","Over time, you may become more careful about raising concerns. You know how much effort it takes to return to normal, so a reasonable need begins to feel like a problem you should manage privately.","The quieter loss is confidence in your own perspective. Being able to restore closeness does not mean your need was unreasonable, and agreeing to end a disagreement does not prove the disagreement was resolved."]}],"deeper":[{"id":"anxious-reassurance","title":"Why reassurance can fade so quickly","preview":"One answer can settle this moment without settling what the next silence means to you.","paragraphs":["A reassuring answer addresses the worry you brought into a particular conversation. It may not change the expectation you carry into the next one: will support still be there when I need it again? That is why feeling better now and checking again later can coexist.","Your answers show where this happens, rather than proving you distrust everyone. It may be strongest around messages, unfinished conflict, or a request you are afraid will be refused. Different situations can bring out different responses.","Repeated inconsistency from another person also matters. The same urge to check can occur when there is little new evidence, or when someone actually keeps breaking agreements. Your relationship-background answers help separate those possibilities."]},{"id":"anxious-cost","title":"What you may slowly stop allowing yourself","preview":"The relationship can take up more space while your own limits become harder to hear.","paragraphs":["If keeping the bond intact becomes the first priority, your attention may stay on what will reassure the other person or prevent another withdrawal. Rest, disagreement, and a clear no can begin to feel expensive.","You may still function well in the rest of your life while one relationship consumes a surprising amount of thought. This does not make the relationship more meaningful by itself; it describes how much work uncertainty is asking you to do.","The important distinction in this report is between caring about someone and repeatedly abandoning your own experience to keep contact. Your selected answers show where that pressure is most familiar."]}]},"avoidant":{"label":"Avoidant attachment","headline":"You know how to carry it alone. Letting someone in is less familiar.","summary":"You often turn toward yourself when feelings are difficult, and create space when closeness becomes demanding. Other people may see independence without realizing that you also have needs you rarely bring into the conversation.","traits":["You tend to process difficult feelings on your own.","You may lower your expectations before asking for more.","After sharing something personal, you can want to close the conversation down.","Closeness can feel pressuring when you cannot see enough room for yourself.","Once you feel calmer, you may hope the difficult subject will pass."],"risks":[{"id":"avoidant-pressure","title":"When closeness starts to feel like a demand","preview":"The more urgently someone asks for access, the less you may feel able to speak.","paragraphs":["If someone repeatedly demands immediate answers, more contact, or disclosures you are not ready to make, closeness can start to feel like losing control over your own time and feelings. Creating distance may bring immediate relief.","A loop can form if they respond to that distance by pressing harder. You may speak less because you feel pushed; they may push because you speak less. Each person reacts to the last move, while the actual need underneath becomes harder to hear.","Needing space does not by itself make you unavailable. The risk grows when no pause is allowed, or when withdrawing becomes the only response and there is never a return. Both the pressure and the follow-through matter."]},{"id":"avoidant-silent","title":"The distance that grows while everything looks calm","preview":"Not arguing can feel peaceful even while important things stay unsaid.","paragraphs":["You may feel that an issue has passed once the intensity inside you settles. The other person may still be waiting to understand what happened or whether it will happen again. You can be in the same room and be at very different points in the conversation.","When this repeats, they may ask less, and you may feel relieved that there is less tension. But fewer questions can also mean that someone has stopped expecting an answer. Quiet is not enough information to tell those situations apart.","The cost can arrive late: emotional distance that seemed sudden has actually grown around a series of unfinished moments. Your conflict and return-to-conversation answers indicate whether this is a familiar risk for you."]},{"id":"avoidant-needs","title":"When needing less starts to cost you more","preview":"People can only respond to the needs they have some chance to understand.","paragraphs":["Telling yourself that you should not need so much can keep a relationship feeling undemanding. It can also remove the opportunity to find out whether this person would respond differently if they knew what you wanted.","You may become skilled at adjusting privately: expecting less contact, not mentioning disappointment, or solving a difficult week alone. Other people can mistake those adjustments for genuine preference. They may not know how much effort it takes to seem fine.","The cost is not only missed support. It can be resentment that has no shared explanation: you feel alone in carrying things, while the other person has never understood how alone you feel. Respect for your privacy and room for your needs both matter."]}],"deeper":[{"id":"avoidant-reliance","title":"When did relying on yourself become the only real option?","preview":"Your family answers help distinguish a familiar habit of self-reliance from a history we should not assume.","paragraphs":["Some people remember asking caregivers for help and repeatedly finding that the support they needed was not available. Over time, asking can begin to feel pointless: the problem will still be theirs to handle. If you selected that experience, the matching family section explores it directly.","Others remember reliable early care and became more guarded after a later relationship, or simply recognize a present habit without identifying one clear origin. Being avoidant in these answers cannot tell us which family you came from. Your actual background choices determine what follows.","What the current answers can show is the move toward handling things privately. Being capable and feeling able to ask are different experiences. A person can be good at carrying a problem and still rarely experience help as a real option."]},{"id":"avoidant-guard","title":"Why “you can rely on me” may not feel reassuring yet","preview":"An offer can be sincere and still feel unfamiliar to receive.","paragraphs":["An offer of support can create questions before it creates relief. Will they understand? Will I still have room to decide what I share? What happens if I let myself expect something and it does not arrive? Which of these fits depends on your selected reactions and experiences.","You may keep part of the story private, accept practical help while withholding the feeling, or retreat after a moment of disclosure. Each move keeps the amount of dependence manageable. It can also make it difficult for another person to discover how to be there for you.","The result is a relationship in which you may be cared about without often feeling cared for. This is a possible consequence of the responses you selected, not proof that every offer is safe or that every limit should be removed."]}]},"fearful":{"label":"Fearful-avoidant attachment","headline":"You want to be close, and keep a way to protect yourself.","summary":"You may reach for connection and then feel exposed when it arrives. A need comes out and is taken back; distance feels safer until you begin to miss the person. Wanting care and wanting protection can show up in the same moment.","traits":["You can want contact and hesitate to show how much.","Affection may bring relief followed by worry.","You may regret sharing soon after feeling understood.","Commitment can be wanted and unsettling at the same time.","Pulling away can be followed by a renewed fear of losing the connection."],"risks":[{"id":"fearful-shift","title":"When each change in direction starts another test","preview":"You move closer, feel exposed, and pull back; the response can restart the worry.","paragraphs":["Reaching out can briefly answer the fear of being forgotten. Being received can raise another concern: now this person can see how much they matter. Pulling back then reduces the exposure while creating fresh distance.","The other person may respond to that distance with their own uncertainty, urgency, or withdrawal. You can end up reacting to a response that your last protective move helped create. That does not make the whole relationship your responsibility; it describes one possible feedback loop.","Over time, both people can spend more effort interpreting each other than saying what they mean. Small delays and changes of tone become tests, and neither person feels sure which version of the connection will appear next."]},{"id":"fearful-unpredictable","title":"When unpredictable care keeps you on watch","preview":"A good moment can feel real without becoming a stable expectation.","paragraphs":["If another person sometimes responds warmly and sometimes shuts you out or dismisses your needs, it is difficult to know what opening up will lead to. Feeling relieved during one conversation may not help you predict the next.","For someone who already recognizes both reaching and retreating, that uncertainty can reinforce the urge to keep an exit available. You may be moved by care and quickly look for signs that it is about to change.","The cost can be losing the chance to rest in either direction. Staying close requires monitoring; staying distant brings longing. Your partner-response answers indicate whether this unpredictability is something you actually described, rather than something a label allows us to assume."]},{"id":"fearful-unheard","title":"When your request is hidden by what you do next","preview":"The person may hear “leave me alone” when the feeling underneath is much less simple.","paragraphs":["You may ask for reassurance and then dismiss it, agree to meet and want to cancel, or share something personal and quickly change the subject. Each response can make sense as protection in the moment. Taken together, they can make your request hard to recognize.","The other person may stop offering the thing you hoped for because they understand the withdrawal as a clear no. Or they may keep pressing, which can feel intrusive. Neither outcome automatically explains what you actually wanted.","The hidden cost is the feeling of being misunderstood while only part of the need has been visible. The specific answers you chose show where that split is most familiar, rather than treating every disagreement as the same problem."]}],"deeper":[{"id":"fearful-both","title":"Why distance and closeness can both unsettle you","preview":"The wish for support does not always cancel the wish to stay protected.","paragraphs":["Distance may raise the possibility of losing someone. Closeness may raise the possibility of relying on them, being seen, or being hurt later. If both concerns become active, neither moving forward nor pulling back feels fully settled.","This can make your own reactions seem inconsistent to you. A warm evening may be followed by wanting space; wanting space may be followed by checking whether they still care. The sequence matters more than treating any one moment as the whole story.","This result describes the approach-and-retreat reactions in your choices. It does not establish a childhood diagnosis or tell us that a particular harmful event occurred. Family and later-experience sections use only the backgrounds you actually selected."]},{"id":"fearful-trust","title":"Why reassurance and trust may move at different speeds","preview":"You can believe the caring words for a moment and still keep protecting yourself.","paragraphs":["A reassuring sentence can reach the part of you that wants connection. The part that anticipates hurt may still want more information. Both reactions can be present without either one being a performance.","If you have selected experiences of criticism, unpredictable responses, or trust not being respected, those passages explore possible links. If you selected steady care instead, the report preserves that too; it will not replace it with a more dramatic story.","The relationship cost appears when protection happens so quickly that a reliable response never has time to become part of your expectations. Actual repeated inconsistency is different, and should not be explained away as only your difficulty trusting."]}]},"secure":{"label":"Secure attachment","headline":"You can care about the relationship and keep room for yourself.","summary":"You tend to express what you need, allow room for time apart, and return to difficult conversations. You can still feel hurt or uncertain, while using what actually happens to judge the relationship instead of having to re-establish your worth each time.","traits":["You can make a need specific enough to discuss.","Time apart can coexist with a clear plan to reconnect.","You can accept support while choosing what to share.","A disagreement does not have to end the conversation.","Reliable follow-through can become part of your trust."],"risks":[{"id":"secure-promises","title":"When your willingness to understand keeps meeting the same broken promise","preview":"Being able to see their perspective does not make repeated non-delivery harmless.","paragraphs":["You may be able to consider reasons, allow time, and avoid jumping to the worst conclusion. Those responses can support a relationship in which both people act in good faith. They can also leave you waiting if explanations keep replacing actual follow-through.","A calm response from you does not change whether an agreement was kept. If the same disappointment repeats, understanding the circumstances and acknowledging the pattern are both relevant. You do not have to become more visibly distressed before a need counts.","The cost can be patience that slowly stops feeling chosen. This risk is especially relevant if your background answers describe promises without action; the report does not assume that your partner behaves this way."]},{"id":"secure-one-sided","title":"When being good at communication becomes doing it for both people","preview":"A relationship can look workable because you keep making the conversations happen.","paragraphs":["You may be willing to listen, name your part, and return after a pause. If only one person consistently does these things, the relationship can still become uneven. Your ability to restore contact does not show that responsibility is being shared.","Over time, the work may become almost invisible: finding the right moment, clarifying the misunderstanding, raising the unresolved issue again. You can remain composed while becoming tired of carrying the process.","The relevant question is whether there is participation from the other side. Someone can need time or communicate differently and still return, listen, and follow through. Permanent absence from that work is a different pattern."]},{"id":"secure-boundaries","title":"When small exceptions slowly become a relationship you did not agree to","preview":"Flexibility can feel generous until your own limits are repeatedly the part that moves.","paragraphs":["A flexible response can help two people find an arrangement that works. If the same person always adjusts, the exception can quietly become the expectation. You may notice the strain only after the arrangement has been repeated many times.","Being secure in these answers does not make every relationship suitable for you. A reasonable need can remain unmet even when you express it clearly. The other person may be unable or unwilling to offer what the relationship requires.","The cost is treating your ability to cope as evidence that the arrangement is acceptable. How well you handle disappointment and whether you want to keep living with it are separate questions."]}],"deeper":[{"id":"secure-room","title":"What a steadier expectation of support makes possible","preview":"You can have a need without making the whole relationship depend on one immediate response.","paragraphs":["Your selected answers suggest that a pause, a disagreement, or a limit can remain a specific event rather than immediately becoming a judgment about your value. This leaves more room to hear explanations and notice what happens next.","That does not mean you feel calm at every moment. You can be upset, need reassurance, and want someone to show up. The difference in these choices is the room to express the need and consider the response without having only one way to protect yourself.","The family section may describe reliable early support if you selected it. Later consistent care can also be part of the story. Your present responses do not prove that childhood was perfect or that difficult experiences were absent."]},{"id":"secure-reality","title":"Trust can include noticing when something does not work","preview":"Being open does not require you to turn every disappointment into a misunderstanding.","paragraphs":["Trust lets you use reliable experience instead of starting over at every uncertain moment. It also leaves room for new information. Someone repeatedly failing to return or respect a clear limit is information, even if you can understand why they struggle.","Your steadier responses are useful because they make the relationship easier to see, not because they guarantee it will succeed. The report pairs them with your actual descriptions of the other person so that genuine reliability and repeated difficulty remain distinct.","You can value a relationship without making your ability to tolerate it the only measure of whether it works. The needs you can express clearly still deserve an answer."]}]}}}') ON CONFLICT(version) DO NOTHING;
INSERT INTO quiz_questions(id,test_id,kicker,prompt,atlas_path,options_json,report_config_json,position,active) VALUES ('attachment-style-fixed-v2-q01','attachment-style','Contact and distance','They usually keep in touch, but you have not heard from them for several hours. What do you do first?','','[{"optionId":"q01-a","label":"I keep checking my phone, then send a few more messages.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q01-a","tag":"reassurance","title":"Waiting makes it hard to put your phone down","reading":"When contact stops, it can be hard to bring your attention back to your own day. Sending another message may be your way of checking that the connection is still there.","preview":"When contact stops, it can be hard to bring your attention back to your own day.","reviewZh":{"label":"反复看手机，又忍不住接着发几条消息。","reading":"当联系突然停下来，你很难把注意力放回自己的生活。你可能通过继续发消息，尽快确认你们之间没有出问题。"}}},{"optionId":"q01-b","label":"I pull my attention back and feel less interested in reaching out.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q01-b","tag":"distance","title":"You lower your expectations before you get more invested","reading":"When a reply does not come, you lower your expectations. Pulling back your attention can help you feel less affected by what the other person does.","preview":"When a reply does not come, you lower your expectations.","reviewZh":{"label":"把注意力收回来，也不太想主动联系了。","reading":"当回应没有出现，你会先把期待降下来。与其一直等，你更习惯收回投入，让自己的心情少受对方影响。"}}},{"optionId":"q01-c","label":"I check in once, then get on with what I am doing.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q01-c","tag":"space","title":"You can keep living your day while you wait","reading":"You notice the change and can leave room for a reply. This pause alone is not enough for you to decide that something is wrong between you.","preview":"You notice the change and can leave room for a reply.","reviewZh":{"label":"问候一次，然后继续忙自己的事。","reading":"你会在意联系的变化，也能留出等待的空间。这一次没有回复，暂时还不足以让你认定关系出了问题。"}}},{"optionId":"q01-d","label":"I want to message again, but hold back because I do not want to seem too invested.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q01-d","tag":"push-pull","title":"You want contact and hesitate to show it","reading":"You want to know the connection is still there, and you also want to protect how much you reveal. Your phone may stay quiet while you keep going back and forth inside.","preview":"You want to know the connection is still there, and you also want to protect how much you reveal.","reviewZh":{"label":"很想再发消息，却又怕显得太在乎，最后忍着不发。","reading":"你想确认联系还在，也想保护自己不被看出有多在意。手机上看起来安静，心里却可能一直在犹豫。"}}},{"optionId":"q01-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q01-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Contact and distance","sourceNumber":1}',1,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions(id,test_id,kicker,prompt,atlas_path,options_json,report_config_json,position,active) VALUES ('attachment-style-fixed-v2-q02','attachment-style','Contact and distance','They cancel a plan, explain why, and suggest another day. What tends to happen for you?','','[{"optionId":"q02-a","label":"I still wonder whether I matter as much as I thought.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q02-a","tag":"reassurance","title":"A changed plan makes you question your place","reading":"Even with an explanation, disappointment can turn into a question about your place in the relationship. What matters is not only the missed plan, but whether you are being kept in mind.","preview":"Even with an explanation, disappointment can turn into a question about your place in the relationship.","reviewZh":{"label":"还是忍不住想：我是不是没那么重要？","reading":"即使对方给出解释，失望也可能很快变成对自己位置的怀疑。你在意的不只是这次见面，而是自己有没有被放在心上。"}}},{"optionId":"q02-b","label":"I lower my expectations and prefer to make my own plans next time.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q02-b","tag":"distance","title":"You expect less so the next letdown hurts less","reading":"One disappointment can make you adjust how much you expect. Taking your plans back into your own hands may feel easier than depending on the next agreement.","preview":"One disappointment can make you adjust how much you expect.","reviewZh":{"label":"降低期待，后面尽量自己安排，不太想再依赖约定。","reading":"一次落空可能让你迅速调整投入：之后少期待一点，就不用再被同样的事影响。你会先把生活安排重新放回自己手里。"}}},{"optionId":"q02-c","label":"I feel disappointed, but can agree on a new time.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q02-c","tag":"repair","title":"You consider the explanation and the follow-through","reading":"You can acknowledge your disappointment while considering the explanation and what happens next. A cancelled plan does not immediately become a verdict on the whole relationship.","preview":"You can acknowledge your disappointment while considering the explanation and what happens next.","reviewZh":{"label":"有些失望，但可以商量好新的时间。","reading":"你能承认自己失望，也愿意结合解释和后续行动判断。取消一次计划，没有立刻变成对整段关系的否定。"}}},{"optionId":"q02-d","label":"I agree to reschedule but want to pull away, then look forward to seeing them again.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q02-d","tag":"push-pull","title":"You want the meeting and hesitate to look forward to it","reading":"You still want to see them, but hesitate to get your hopes up again. Wanting closeness and wanting protection can take turns around the same plan.","preview":"You still want to see them, but hesitate to get your hopes up again.","reviewZh":{"label":"答应改时间，心里却想退开；临近见面又很期待。","reading":"你依然想见对方，却不太敢重新投入期待。想靠近和怕再次落空，会在这一次安排里轮流出现。"}}},{"optionId":"q02-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q02-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Contact and distance","sourceNumber":2}',2,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions(id,test_id,kicker,prompt,atlas_path,options_json,report_config_json,position,active) VALUES ('attachment-style-fixed-v2-q03','attachment-style','Contact and distance','After a busy week, they ask for an evening alone. What feels most familiar?','','[{"optionId":"q03-a","label":"I say okay, but look for signs that they are not pulling away.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q03-a","tag":"reassurance","title":"You give space while checking the connection","reading":"You can agree to give space while still needing a sign that the relationship has not changed. Time apart may draw your attention toward whether the closeness is still there.","preview":"You can agree to give space while still needing a sign that the relationship has not changed.","reviewZh":{"label":"嘴上说好，还是想确认对方没有疏远我。","reading":"你可以答应给空间，但心里可能仍需要一个关系没有变化的信号。对方暂时离开时，你更容易留意亲密感是不是还在。"}}},{"optionId":"q03-b","label":"I feel relieved and do not hurry to arrange our next contact.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q03-b","tag":"distance","title":"Distance feels easier than arranging the next connection","reading":"Some distance feels comfortable, and reconnecting can become easy to put off. What matters is whether that delay keeps happening, rather than enjoying one evening to yourself.","preview":"Some distance feels comfortable, and reconnecting can become easy to put off.","reviewZh":{"label":"松了一口气，也不急着安排下一次联系。","reading":"分开一会儿会让你更自在，你也容易把重新联系往后放。要看的是这种延后是否反复出现，而不只是这一次享受独处。"}}},{"optionId":"q03-c","label":"I let them rest and agree on when we will catch up.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q03-c","tag":"space","title":"Space and connection can coexist for you","reading":"You can make room for space and connection together. A clear next point of contact lets you return to your own plans without treating an evening apart as rejection.","preview":"You can make room for space and connection together.","reviewZh":{"label":"让对方休息，顺便约好之后什么时候联系。","reading":"你能同时照顾彼此的空间和联系。分开一晚不会自动意味着疏远，有一个清楚的约定就能让你继续自己的安排。"}}},{"optionId":"q03-d","label":"I want to respect the space, then feel hurt and want distance myself.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q03-d","tag":"push-pull","title":"You want to give space, then pull back further","reading":"You want them to feel comfortable, but the request can also land as rejection. Pulling away in return may protect you from feeling like the one who needs the relationship more.","preview":"You want them to feel comfortable, but the request can also land as rejection.","reviewZh":{"label":"想尊重对方，但又觉得受伤，转而也不想理对方。","reading":"你想让对方自在，也会把这次分开感受成一种拒绝。为了不显得自己更需要关系，你可能跟着把距离拉大。"}}},{"optionId":"q03-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q03-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Contact and distance","sourceNumber":3}',3,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions(id,test_id,kicker,prompt,atlas_path,options_json,report_config_json,position,active) VALUES ('attachment-style-fixed-v2-q04','attachment-style','Closeness and support','As the relationship grows, they become more affectionate and attentive. What do you usually notice?','','[{"optionId":"q04-a","label":"I feel happy, but keep checking whether they really care.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q04-a","tag":"reassurance","title":"You enjoy care and want to know it will last","reading":"The attention feels good, yet it may be hard to stay with that moment. You also want to know whether the affection will continue instead of fading soon.","preview":"The attention feels good, yet it may be hard to stay with that moment.","reviewZh":{"label":"很开心，还是想反复确认对方是不是真的在乎。","reading":"关心会让你开心，但你可能很难只停留在这一刻。你还想确认，这份喜欢能不能继续，而不是很快就变淡。"}}},{"optionId":"q04-b","label":"I feel uncomfortable and want a little less contact.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q04-b","tag":"distance","title":"More closeness can make you want more room","reading":"More closeness can make your own space feel smaller. Less contact may help you feel comfortable again, while leaving them uncertain about how close you want to be.","preview":"More closeness can make your own space feel smaller.","reviewZh":{"label":"有些不自在，想少联系一点，留出距离。","reading":"亲密增加时，你可能先感觉自己的空间变小了。减少联系会让你恢复自在，却也可能让对方摸不清你愿意靠近到哪里。"}}},{"optionId":"q04-c","label":"I feel happy and naturally respond with affection.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q04-c","tag":"closeness","title":"You can receive affection and respond to it","reading":"You can receive care and express your own affection. In this situation, closeness tends to feel like something you can take part in and enjoy.","preview":"You can receive care and express your own affection.","reviewZh":{"label":"开心，也自然地回应对方的亲近。","reading":"你可以接受关心，也愿意表达自己的喜欢。此刻的亲近对你来说，通常是可以参与和享受的。"}}},{"optionId":"q04-d","label":"I feel happy at first, then worry they will change their mind and hold back.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q04-d","tag":"push-pull","title":"Feeling close can bring the fear of losing it","reading":"Care can move you and then make you more watchful. As the relationship matters more, the possibility of losing it can feel more difficult to face.","preview":"Care can move you and then make you more watchful.","reviewZh":{"label":"一开始开心，随后担心对方变心，又把自己收回去。","reading":"你会被关心打动，也可能在打动之后开始防备。越感到这段关系重要，你越怕投入后承受失去。"}}},{"optionId":"q04-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q04-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Closeness and support","sourceNumber":5}',4,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions(id,test_id,kicker,prompt,atlas_path,options_json,report_config_json,position,active) VALUES ('attachment-style-fixed-v2-q05','attachment-style','Closeness and support','You have had a hard day. Someone you trust offers to listen without trying to fix it. What do you do?','','[{"optionId":"q05-a","label":"I talk, but keep worrying that I am becoming a burden.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q05-a","tag":"burden","title":"You share your hurt while worrying you are too much","reading":"Even with someone willing to listen, you may monitor how much space you are taking. You need support and also worry about what needing it will do to their view of you.","preview":"Even with someone willing to listen, you may monitor how much space you are taking.","reviewZh":{"label":"会说，但一直担心自己是不是让对方觉得烦。","reading":"即使对方愿意听，你也可能一边表达，一边检查自己有没有占用太多。你需要支持，也在意表达需要会不会影响对方对你的看法。"}}},{"optionId":"q05-b","label":"I say I am fine and would rather deal with it myself.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q05-b","tag":"self-reliance","title":"Even when help is offered, you turn to yourself first","reading":"When someone offers to listen, you still turn toward a familiar response: getting through it yourself. Asking for support may feel less natural than carrying the feeling alone.","preview":"When someone offers to listen, you still turn toward a familiar response: getting through it yourself.","reviewZh":{"label":"说自己没事，还是更习惯自己消化。","reading":"有人愿意听时，你仍会先回到熟悉的处理方式：自己撑过去。开口求助对你来说，可能比独自消化更不习惯。"}}},{"optionId":"q05-c","label":"I share what I want to share and let them be there.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q05-c","tag":"support","title":"You can accept support and keep your own boundaries","reading":"You can choose how much to disclose and allow someone to support you. Accepting company does not mean handing over all your privacy or your ability to handle the problem.","preview":"You can choose how much to disclose and allow someone to support you.","reviewZh":{"label":"说出愿意分享的部分，让对方陪我一会儿。","reading":"你可以决定分享多少，也允许别人参与支持。接受陪伴并不要求你交出全部隐私或解决问题的主动权。"}}},{"optionId":"q05-d","label":"I start to talk, then pull back when it begins to feel vulnerable.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q05-d","tag":"push-pull","title":"You want understanding and fear being seen too closely","reading":"You want to be understood, yet being seen can also feel unsettling. After letting them a little closer, you may want to take something back so you feel protected again.","preview":"You want to be understood, yet being seen can also feel unsettling.","reviewZh":{"label":"想说，也开了口，但说到脆弱的地方就想停下来。","reading":"你希望被理解，也可能在真正被看见时感到不安。你靠近了一点，又会想收回一部分，确认自己仍然安全。"}}},{"optionId":"q05-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q05-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Closeness and support","sourceNumber":6}',5,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions(id,test_id,kicker,prompt,atlas_path,options_json,report_config_json,position,active) VALUES ('attachment-style-fixed-v2-q06','attachment-style','Closeness and support','You have just shared something personal with them. What usually happens afterward?','','[{"optionId":"q06-a","label":"I watch their reaction and wonder whether I said too much.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q06-a","tag":"reassurance","title":"After opening up, you wait for a sign of acceptance","reading":"After sharing, your attention can move toward what they now think of you. A clear sign of acceptance may feel necessary before you can trust that opening up has not changed the relationship.","preview":"After sharing, your attention can move toward what they now think of you.","reviewZh":{"label":"盯着对方的反应，担心自己是不是说多了。","reading":"分享过后，你的注意力容易转到对方怎么看你。你可能需要一个明确的接纳信号，才敢相信这次表达没有让关系变差。"}}},{"optionId":"q06-b","label":"I change the subject and keep the next conversation lighter.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q06-b","tag":"self-reliance","title":"You close up the part you just opened","reading":"When a conversation touches something vulnerable, you tend to make it lighter again. Saying less can restore your sense of control over how close the other person gets.","preview":"When a conversation touches something vulnerable, you tend to make it lighter again.","reviewZh":{"label":"换个话题，下一次也尽量少谈这些。","reading":"一旦话题触及自己的脆弱，你会倾向于把交流重新变轻。少说一点，能让你重新掌握彼此靠近的程度。"}}},{"optionId":"q06-c","label":"I feel a little exposed, but let their response unfold.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q06-c","tag":"closeness","title":"You can let your words stay in the relationship","reading":"You can tolerate some discomfort after sharing without immediately taking it back. Their response matters, but it does not instantly decide whether you were allowed to say it.","preview":"You can tolerate some discomfort after sharing without immediately taking it back.","reviewZh":{"label":"有一点不自在，但愿意听听对方怎么回应。","reading":"你可以容纳分享之后的短暂不自在，而不急着撤回表达。对方的回应会参与判断，但不会立刻决定你能不能说这些。"}}},{"optionId":"q06-d","label":"I feel closer briefly, then regret sharing and want to take it back.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q06-d","tag":"push-pull","title":"A moment of closeness is followed by an urge to retreat","reading":"The relief of closeness and the feeling of exposure may arrive together. Soon after letting them in, you may start wondering whether you gave away too much.","preview":"The relief of closeness and the feeling of exposure may arrive together.","reviewZh":{"label":"刚觉得更亲近，很快又后悔，想把刚才的话收回去。","reading":"亲近带来的轻松和暴露感可能同时存在。你刚允许对方靠近，就又开始担心自己是不是交出去太多。"}}},{"optionId":"q06-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q06-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Closeness and support","sourceNumber":7}',6,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions(id,test_id,kicker,prompt,atlas_path,options_json,report_config_json,position,active) VALUES ('attachment-style-fixed-v2-q07','attachment-style','Closeness and support','When you begin talking seriously about a future together, which thought feels most familiar?','','[{"optionId":"q07-a","label":"I keep wondering whether they are as serious about this as I am.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q07-a","tag":"reassurance","title":"You want to know you are not the only one imagining a future","reading":"Talking about the future increases your need to know the investment is mutual. One statement may not settle it; you may keep looking for signs that they mean it as much as you do.","preview":"Talking about the future increases your need to know the investment is mutual.","reviewZh":{"label":"反复想：对方是不是和我一样认真？","reading":"谈未来会让你更想确认投入是否对等。你可能难以只听一次表态，而会继续寻找对方同样认真的证据。"}}},{"optionId":"q07-b","label":"I worry there will be too many expectations and too little room for myself.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q07-b","tag":"distance","title":"You wonder how much room commitment will leave you","reading":"You first notice the responsibilities and limits that commitment might bring. As the relationship becomes more defined, you may need to know that your choices and personal space still belong to you.","preview":"You first notice the responsibilities and limits that commitment might bring.","reviewZh":{"label":"担心以后会有太多要求，自己的空间越来越少。","reading":"你会先注意承诺可能带来的责任和限制。关系变得更确定时，你可能更需要确认自己仍有选择和独处的空间。"}}},{"optionId":"q07-c","label":"I want to understand whether our expectations and pace fit.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q07-c","tag":"clarity","title":"You want a future you have actually talked through","reading":"You care about the future and want to discuss it in concrete terms. Commitment involves understanding each other, rather than only getting an immediate yes.","preview":"You care about the future and want to discuss it in concrete terms.","reviewZh":{"label":"想了解双方的期待和节奏能不能合得来。","reading":"你重视未来，也愿意通过具体讨论了解彼此。承诺需要双方看清和商量，而不只是立刻得到一个肯定答案。"}}},{"optionId":"q07-d","label":"I want the commitment, but start backing away when they seriously agree.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q07-d","tag":"push-pull","title":"You want commitment and hesitate when it becomes real","reading":"You want the relationship to become certain, and can become watchful when that certainty feels real. Wanting it and pulling away can make your own decision feel confusing.","preview":"You want the relationship to become certain, and can become watchful when that certainty feels real.","reviewZh":{"label":"很想确定下来，但对方认真答应时，我又想往后退。","reading":"你渴望确定关系，也可能在承诺变得真实时警觉。期待和退缩并存，会让你对自己的决定也感到困惑。"}}},{"optionId":"q07-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q07-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Closeness and support","sourceNumber":8}',7,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions(id,test_id,kicker,prompt,atlas_path,options_json,report_config_json,position,active) VALUES ('attachment-style-fixed-v2-q08','attachment-style','Conflict and repair','A disagreement is becoming more heated. What is your usual first move?','','[{"optionId":"q08-a","label":"I keep talking and asking questions because leaving it unresolved feels worse.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q08-a","tag":"pursuit","title":"Leaving it unresolved feels harder than continuing","reading":"An unresolved issue can make it hard to settle. Trying to restore the connection immediately may keep the conversation going beyond the point when either person can take much in.","preview":"An unresolved issue can make it hard to settle.","reviewZh":{"label":"继续追问、继续说，没说清楚就很难停下来。","reading":"悬着的问题会让你很难安心。你可能想通过当场谈清楚，尽快恢复联系，却忽略了双方此时已经很难听进去。"}}},{"optionId":"q08-b","label":"I go quiet or leave before saying much about what I feel.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q08-b","tag":"withdrawal","title":"Under pressure, you first take yourself out of the conversation","reading":"As tension rises, you reduce contact to get out of the pressure. What that pause means for the relationship also depends on whether you come back to explain and reconnect afterward.","preview":"As tension rises, you reduce contact to get out of the pressure.","reviewZh":{"label":"变得沉默，或者先离开，很少说自己的感受。","reading":"紧张上来时，你会先减少交流，让自己从压力里退出来。这个动作是否伤害关系，还要看之后有没有回来说明和沟通。"}}},{"optionId":"q08-c","label":"I ask for a pause and say when I can return to the conversation.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q08-c","tag":"repair","title":"You make room to cool down and still plan to return","reading":"You give your feelings room to settle while making it clear that the conversation is not being abandoned. The pause and the return are connected in your response.","preview":"You give your feelings room to settle while making it clear that the conversation is not being abandoned.","reviewZh":{"label":"提出暂停，也说明什么时候可以回来继续谈。","reading":"你会给情绪留出缓冲，同时让对方知道对话没有被放弃。暂停和恢复联系，在你的做法里是连在一起的。"}}},{"optionId":"q08-d","label":"I want them close, then tell them to go away when my feelings get stronger.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q08-d","tag":"push-pull","title":"The need for care can come out sounding like rejection","reading":"You may want comfort and push it away when your feelings intensify. The distance you ask for can end up being the opposite of the contact you hoped to receive.","preview":"You may want comfort and push it away when your feelings intensify.","reviewZh":{"label":"想让对方靠近，一激动又说出让对方走开的话。","reading":"你需要安慰，也可能在情绪变强时推开对方。说出口的距离，可能和你当时想获得的联系相反。"}}},{"optionId":"q08-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q08-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Conflict and repair","sourceNumber":9}',8,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions(id,test_id,kicker,prompt,atlas_path,options_json,report_config_json,position,active) VALUES ('attachment-style-fixed-v2-q09','attachment-style','Conflict and repair','They tell you that something you did hurt them. What comes up first?','','[{"optionId":"q09-a","label":"I fear they will pull away and rush to check whether we are okay.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q09-a","tag":"pursuit","title":"You worry about losing the connection before understanding the hurt","reading":"Hearing that they are hurt may immediately raise the possibility of losing them. Getting reassurance that the relationship is okay can take priority over understanding what happened.","preview":"Hearing that they are hurt may immediately raise the possibility of losing them.","reviewZh":{"label":"怕对方因此疏远，急着确认我们还好不好。","reading":"听到对方受伤，你可能立刻担心关系会不会失去。你会先争取“我们还好”的确认，具体发生了什么反而容易被挤到后面。"}}},{"optionId":"q09-b","label":"I want to explain the facts and avoid a long conversation about feelings.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q09-b","tag":"withdrawal","title":"You can explain the facts and still leave the feelings outside","reading":"Explaining what happened is a familiar way to handle a problem. Talking about feelings can be less comfortable, and they may leave the conversation feeling that their hurt was not heard.","preview":"Explaining what happened is a familiar way to handle a problem.","reviewZh":{"label":"想把事情解释清楚，但不太想继续谈感受。","reading":"你更习惯通过说明事实处理问题。感受的讨论会让你不自在，却也可能让对方觉得自己的难过没有被听见。"}}},{"optionId":"q09-c","label":"I feel defensive, but want to hear what hurt them.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q09-c","tag":"repair","title":"You stay open to understanding while feeling uncomfortable","reading":"You notice your defensiveness and remain willing to understand their experience. Listening does not mean accepting every accusation; it leaves room to understand and repair.","preview":"You notice your defensiveness and remain willing to understand their experience.","reviewZh":{"label":"虽然有些防御，还是想先听清楚哪里伤到了对方。","reading":"你能注意到自己的防御，也愿意理解对方的体验。听进去并不等于立刻认同所有指责，而是给修复留下入口。"}}},{"optionId":"q09-d","label":"I want to repair it, but also want to hide from their reaction.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q09-d","tag":"push-pull","title":"You want to put it right and hide at the same time","reading":"Repair matters to you, and facing their response can feel difficult. The urge to make things right and the urge to escape may both make a clear conversation harder to begin.","preview":"Repair matters to you, and facing their response can feel difficult.","reviewZh":{"label":"想修复，又怕面对对方的反应，想暂时躲起来。","reading":"你在乎修复，也很怕接下来会发生什么。想补救和想躲开的冲动，可能同时让你难以开始一段清楚的对话。"}}},{"optionId":"q09-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q09-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Conflict and repair","sourceNumber":10}',9,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions(id,test_id,kicker,prompt,atlas_path,options_json,report_config_json,position,active) VALUES ('attachment-style-fixed-v2-q10','attachment-style','Conflict and repair','You agreed to return to a difficult conversation later. What usually happens?','','[{"optionId":"q10-a","label":"I contact them before the agreed time because waiting is too hard.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q10-a","tag":"pursuit","title":"An agreed return does not always make waiting easier","reading":"Even with a time agreed, you may keep needing confirmation that the relationship is intact. Reaching out early can interrupt the breathing room you had both planned.","preview":"Even with a time agreed, you may keep needing confirmation that the relationship is intact.","reviewZh":{"label":"还没到约定时间就联系对方，因为等着太难受。","reading":"即使已经约好时间，等待仍可能让你不断想确认关系。你急着恢复联系，也可能打断了原本商量好的缓冲。"}}},{"optionId":"q10-b","label":"Once I feel calmer, I hope we will not need to bring it up again.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q10-b","tag":"withdrawal","title":"You feel calmer, but the issue may still be there","reading":"When the feeling passes, it can seem as though the issue has passed too. They may still be waiting for an explanation, leaving something unresolved between you even while you feel calmer.","preview":"When the feeling passes, it can seem as though the issue has passed too.","reviewZh":{"label":"自己平静下来后，希望这件事就不要再提了。","reading":"情绪过去以后，你容易把“不再难受”当成问题已经过去。对方却可能还在等一次说明，没谈完的事会留在两个人之间。"}}},{"optionId":"q10-c","label":"I return when we agreed, or explain if I need to change the time.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q10-c","tag":"repair","title":"You make the return after a pause actually happen","reading":"You turn the promise to reconnect into something observable. A disagreement need not be solved at once for the other person to know you are still taking it seriously.","preview":"You turn the promise to reconnect into something observable.","reviewZh":{"label":"按约定回来谈；如果需要改时间，会说明。","reading":"你能把暂停之后的承诺落到行动上。分歧不必一次解决，但对方能够知道，这段对话仍然有人在认真对待。"}}},{"optionId":"q10-d","label":"I want to talk, then hesitate when the time comes; afterward I worry we are further apart.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q10-d","tag":"push-pull","title":"You want to reconnect and retreat as the moment arrives","reading":"You want the connection restored and also dread facing the tension again. Pulling back as the conversation approaches can leave you with a new worry about the distance.","preview":"You want the connection restored and also dread facing the tension again.","reviewZh":{"label":"等着重新谈，到了时间又想躲；错过后又担心更疏远。","reading":"你希望关系恢复，却也怕重新面对紧张。临近沟通时的退缩，会让原本想修复的你再次陷入担心。"}}},{"optionId":"q10-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q10-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Conflict and repair","sourceNumber":11}',10,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions(id,test_id,kicker,prompt,atlas_path,options_json,report_config_json,position,active) VALUES ('attachment-style-fixed-v2-q11','attachment-style','Needs and boundaries','They want to see you tonight, but you need time to yourself. What do you usually do?','','[{"optionId":"q11-a","label":"I consider agreeing because I worry that saying no will disappoint them.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q11-a","tag":"burden","title":"Their disappointment can come before your own need","reading":"When your need might disappoint someone, the relationship can come first. Agreeing once means little on its own; repeatedly overriding yourself can build tiredness and resentment.","preview":"When your need might disappoint someone, the relationship can come first.","reviewZh":{"label":"担心拒绝会让对方失望，想勉强答应。","reading":"当自己的需要可能让对方失望时，你容易先照顾关系。一次答应并不说明什么，但反复勉强自己可能让疲惫和委屈累积。"}}},{"optionId":"q11-b","label":"I find a reason to be unavailable without explaining much.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q11-b","tag":"distance","title":"You protect your space without always explaining it","reading":"You protect your time through distance rather than describing what you need. They may know you are not coming without understanding that you simply need rest.","preview":"You protect your time through distance rather than describing what you need.","reviewZh":{"label":"找个理由不见，尽量不解释自己的感受。","reading":"你会用实际距离保护自己的时间，却不太习惯把需要说出来。对方可能知道你不来，却不知道你只是需要休息。"}}},{"optionId":"q11-c","label":"I say I need the evening and discuss another time if I want to.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q11-c","tag":"boundary","title":"You can make your own plans clear","reading":"You make your own plans clear and leave room for a conversation. This describes how you respond in this situation, rather than proving you always handle every boundary the same way.","preview":"You make your own plans clear and leave room for a conversation.","reviewZh":{"label":"直接说今晚需要独处，愿意见面时再商量时间。","reading":"你会把自己的安排说清楚，也给彼此留出商量的空间。这次选择说明的是这一情境里的表达方式，不代表你在所有场景都如此。"}}},{"optionId":"q11-d","label":"I fear they will stop asking if I say no, but want to cancel after agreeing.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q11-d","tag":"push-pull","title":"You fear losing the invitation and then want to take back your yes","reading":"You want to be wanted, and agreeing to closeness can also feel pressuring. Saying yes to keep the connection, then wanting to withdraw to protect your space, can leave you caught between both needs.","preview":"You want to be wanted, and agreeing to closeness can also feel pressuring.","reviewZh":{"label":"怕拒绝后对方不再约我，答应了又想临时取消。","reading":"你希望被邀请和被需要，也可能在答应靠近后感到压力。为了不失去联系而答应，再为保护空间而撤回，会让你更加为难。"}}},{"optionId":"q11-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q11-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Needs and boundaries","sourceNumber":13}',11,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions(id,test_id,kicker,prompt,atlas_path,options_json,report_config_json,position,active) VALUES ('attachment-style-fixed-v2-q12','attachment-style','Needs and boundaries','You wish they would check in more often. What do you usually do?','','[{"optionId":"q12-a","label":"Bring it up repeatedly because I still do not feel sure they really want to.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q12-a","tag":"reassurance","title":"You ask for contact and still question whether it is freely wanted","reading":"You express the need, but one answer may not settle it. Repeating the request can reflect uncertainty about whether they want to come toward you on their own.","preview":"You express the need, but one answer may not settle it.","reviewZh":{"label":"反复提起，因为还是不确定对方是不是真的愿意。","reading":"你会表达需要，但一次答复可能很难让你安心。反复提起的背后，可能是你还没有相信对方愿意主动靠近。"}}},{"optionId":"q12-b","label":"Tell myself I should need less and keep it to myself.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q12-b","tag":"self-reliance","title":"You reduce the need before giving it a chance to be heard","reading":"You try to make your own needs smaller so the relationship feels easier. Over time, they may think you are satisfied without knowing that you had hoped for more.","preview":"You try to make your own needs smaller so the relationship feels easier.","reviewZh":{"label":"告诉自己别需要这么多，最后还是不说。","reading":"你会先尝试把自己的需要压小，让关系保持轻松。时间久了，对方可能以为你一直满意，却不知道你也曾期待更多。"}}},{"optionId":"q12-c","label":"Say what I would like and ask what works for them.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q12-c","tag":"clarity","title":"You give your need a chance to receive a real response","reading":"You make an expectation specific enough to discuss. Their response and follow-through can then give you useful information about what is possible between you.","preview":"You make an expectation specific enough to discuss.","reviewZh":{"label":"说清楚我希望怎样联系，也问对方能做到什么。","reading":"你能把期待变成可以讨论的具体安排。对方如何回应和履行，会成为你判断关系的重要信息。"}}},{"optionId":"q12-d","label":"Start to ask, then say never mind because I feel too needy.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q12-d","tag":"push-pull","title":"Your need comes out and is quickly taken back","reading":"You want them to know what you hope for, and feel exposed when they can see it. Taking it back may ease that discomfort while making your real request harder to understand.","preview":"You want them to know what you hope for, and feel exposed when they can see it.","reviewZh":{"label":"刚提出来，就怕显得太需要对方，又说算了。","reading":"你想让对方知道自己的期待，也怕被看见需要太多。把话收回去会暂时减少不自在，却让对方难以理解你真正想要什么。"}}},{"optionId":"q12-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q12-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Needs and boundaries","sourceNumber":14}',12,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions(id,test_id,kicker,prompt,atlas_path,options_json,report_config_json,position,active) VALUES ('attachment-style-fixed-v2-q13','attachment-style','Stability and trust','The relationship has been steady for several weeks, without obvious conflict or broken promises. What do you notice?','','[{"optionId":"q13-a","label":"I still look for reassurance that their warmth has not started to fade.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q13-a","tag":"reassurance","title":"You keep checking even when things are steady","reading":"Even without an obvious change, you may keep checking the relationship. Trying to protect the stability can make it harder to enjoy the stability you already have.","preview":"Even without an obvious change, you may keep checking the relationship.","reviewZh":{"label":"还是会寻找保证，确认对方的热情没有变淡。","reading":"外部变化不明显时，你仍可能主动检查关系。你想维持这份稳定，但不断确认也可能让自己很难真正享受它。"}}},{"optionId":"q13-b","label":"I start wanting less closeness, without a clear reason I can name.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q13-b","tag":"distance","title":"Steady closeness can still make you want to step back","reading":"As closeness continues, some distance can feel like a way to get comfortable again. What matters is whether this retreat repeats, rather than treating every wish for time alone as avoidance.","preview":"As closeness continues, some distance can feel like a way to get comfortable again.","reviewZh":{"label":"开始想减少一些亲密接触，却又说不清具体原因。","reading":"当关系持续靠近，你可能想通过一点距离恢复自在。需要留意的是这种退开是否反复出现，而不是把所有独处都解释成回避。"}}},{"optionId":"q13-c","label":"I enjoy the relationship and keep enjoying the rest of my life.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q13-c","tag":"space","title":"Stability leaves you more room to be yourself","reading":"Stability leaves you more room for the rest of your life. Closeness and independence can exist together without constant checks to keep the relationship in place.","preview":"Stability leaves you more room for the rest of your life.","reviewZh":{"label":"能享受这段关系，也继续过好自己的生活。","reading":"稳定会让你更有余地投入关系之外的生活。亲近和独立可以同时存在，不必靠持续确认维持联系。"}}},{"optionId":"q13-d","label":"I value the calm, but hold back some investment in case I get hurt later.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q13-d","tag":"push-pull","title":"You want to enjoy the calm and prepare for its ending","reading":"You can recognize what is good and still start preparing to lose it. Holding back may feel protective in the moment while limiting how much of that steadiness you let yourself experience.","preview":"You can recognize what is good and still start preparing to lose it.","reviewZh":{"label":"很珍惜这份稳定，却又提前收回投入，怕以后受伤。","reading":"你已经感受到关系的好，也可能开始为失去它做准备。提前收回投入能让你暂时安心，却会限制你体验这段稳定的程度。"}}},{"optionId":"q13-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q13-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Stability and trust","sourceNumber":17}',13,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions(id,test_id,kicker,prompt,atlas_path,options_json,report_config_json,position,active) VALUES ('attachment-style-fixed-v2-q14','attachment-style','Stability and trust','After a conversation in which they genuinely address your worries, what usually happens next?','','[{"optionId":"q14-a","label":"I feel better briefly, then a small change makes me seek reassurance again.","microcopy":"","meaning":"","projection":"","styleKey":"anxious","fixed":{"id":"q14-a","tag":"reassurance","title":"You receive reassurance and struggle to keep it with you","reading":"Their response can ease the immediate worry without making the reassurance last. The next small change may send you back to checking whether you still matter.","preview":"Their response can ease the immediate worry without making the reassurance last.","reviewZh":{"label":"短暂安心，之后一点变化又让我想重新确认。","reading":"这次回应可以缓解眼前的不安，但安心不容易持续。下一次小变化出现时，你可能又回到重新确认自己是否重要的过程。"}}},{"optionId":"q14-b","label":"I still feel more comfortable handling my feelings myself than relying on the conversation.","microcopy":"","meaning":"","projection":"","styleKey":"avoidant","fixed":{"id":"q14-b","tag":"self-reliance","title":"Handling it yourself still feels more familiar than accepting comfort","reading":"They have responded, and your familiar way of settling is still to work through it alone. Letting someone else take part in comforting you may need more getting used to.","preview":"They have responded, and your familiar way of settling is still to work through it alone.","reviewZh":{"label":"不太习惯靠这样的谈话安心，还是想自己处理感受。","reading":"对方回应了你，你仍可能更信任自己消化感受的方式。让另一个人参与安慰和支持，对你来说需要更多适应。"}}},{"optionId":"q14-c","label":"I can carry the reassurance with me unless something new happens.","microcopy":"","meaning":"","projection":"","styleKey":"secure","fixed":{"id":"q14-c","tag":"trust","title":"One reliable response can become part of your trust","reading":"You can let a reliable response inform what happens next. Without new information, you do not need to keep proving the relationship is safe all over again.","preview":"You can let a reliable response inform what happens next.","reviewZh":{"label":"能把这次回应放在心里，除非出现新的问题。","reading":"你能够把一次可靠的回应带进之后的相处。没有新的情况时，不必不断重新证明关系是否安全。"}}},{"optionId":"q14-d","label":"I want to believe them, but share less and keep some distance just in case.","microcopy":"","meaning":"","projection":"","styleKey":"fearful","fixed":{"id":"q14-d","tag":"push-pull","title":"You want to trust and keep an exit available","reading":"Their response makes you want to trust, and also reminds you how much you could depend on the relationship. Keeping a little distance lets you believe without feeling completely exposed.","preview":"Their response makes you want to trust, and also reminds you how much you could depend on the relationship.","reviewZh":{"label":"很想相信，但又开始少说少靠近，给自己留退路。","reading":"回应让你想重新信任，也让你意识到自己可能更依赖这段关系。你会在相信的同时保留距离，避免把自己完全交出去。"}}},{"optionId":"q14-skip","label":"Not applicable / Hard to say","microcopy":"","meaning":"","projection":"","fixed":{"id":"q14-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不适用／难以判断","reading":"本题不计分，也不引用为个人特征。继续依据其他有效回答判断。"}}}]','{"version":"attachment-fixed-v2","kind":"core","domain":"Stability and trust","sourceNumber":20}',14,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions(id,test_id,kicker,prompt,atlas_path,options_json,report_config_json,position,active) VALUES ('attachment-style-fixed-v2-q15','attachment-style','Your relationship','Think of a current or recent important romantic relationship. When you try to discuss a disagreement, what does the other person usually do?','','[{"optionId":"q15-a","label":"Talk, or agree on a pause and actually return to the conversation.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q15-a","tag":"partner_returns","title":"A pause can still lead back to connection","reading":"You describe an interaction in which a pause can lead back to a conversation. Returning gives the issue a chance to be addressed. If waiting still feels difficult, that feeling matters too; this particular pause does not by itself mean you are being abandoned.","preview":"You describe an interaction in which a pause can lead back to a conversation.","reviewZh":{"label":"愿意谈；需要暂停时会约好时间，之后也会回来。","reading":"你描述的是一种能够暂停、也能够继续的互动。对方愿意回来，会让问题有机会真正被处理。如果等待期间你仍很难安心，可以结合自己的反应理解，而不必把这次暂停直接当成疏远。"}}},{"optionId":"q15-b","label":"Stop replying or leave, and rarely return to discuss it.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q15-b","tag":"partner_disappears","title":"Waiting without an ending can be what wears you down","reading":"You describe an issue that often has no follow-up. The longer you wait, the more you may question, guess, or stop trying to speak. The cost can accumulate quietly: things look normal again while the hurt that started the conversation remains unresolved.","preview":"You describe an issue that often has no follow-up.","reviewZh":{"label":"不回复或离开，之后也很少再回来谈。","reading":"你面对的是问题经常没有下文的互动。等待越久，你越可能追问、猜测，或者放弃表达。这里需要看清的代价是：关系表面恢复了，未解决的委屈却可能继续累积。"}}},{"optionId":"q15-c","label":"Push for an immediate answer and struggle to allow a pause.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q15-c","tag":"partner_presses","title":"When a pause is not allowed, closeness can feel like pressure","reading":"An immediate demand for answers can leave little room to settle. If you retreat under pressure, the more they push, the harder it may become to speak. Repeated often, a conversation can start feeling like something to escape rather than something you can return to.","preview":"An immediate demand for answers can leave little room to settle.","reviewZh":{"label":"要求马上说清楚，很难接受我需要暂停。","reading":"对方想立刻得到回应，可能让你觉得没有缓冲的空间。你越退，对方越急；对方越急，你越难开口。如果这种互动反复出现，沟通容易变成互相催促和躲避。"}}},{"optionId":"q15-d","label":"It varies: sometimes they engage, and sometimes they suddenly shut me out.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q15-d","tag":"partner_inconsistent","title":"Unpredictable responses make it hard to settle","reading":"You cannot easily predict how the next disagreement will be received. One good conversation may not reassure you because the next one could go very differently. That uncertainty can use up energy you would otherwise put into deciding what you need and whether the relationship works for you.","preview":"You cannot easily predict how the next disagreement will be received.","reviewZh":{"label":"很不固定；有时愿意谈，有时突然不理我。","reading":"你很难预料下一次分歧会被怎样回应。于是，一次好的谈话未必能让你放心，因为下一次仍可能完全不同。这种不确定会消耗你判断关系的精力。"}}},{"optionId":"q15-skip","label":"I do not remember / Not applicable / Prefer not to answer","microcopy":"","meaning":"","projection":"","fixed":{"id":"q15-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不记得／不适用／暂不想回答","reading":"不补写这段经历，不使用依恋类型猜测答案。报告会明确这部分信息不足，并使用其他已经回答的线索。"}}}]','{"version":"attachment-fixed-v2","kind":"relationship","domain":"Your relationship","sourceNumber":4}',15,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions(id,test_id,kicker,prompt,atlas_path,options_json,report_config_json,position,active) VALUES ('attachment-style-fixed-v2-q16','attachment-style','Your relationship','In that same relationship, when you clearly ask for something you need, how does the other person usually respond?','','[{"optionId":"q16-a","label":"Discuss what is possible and usually follow through.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q16-a","tag":"needs_followthrough","title":"Care becomes easier to trust when something happens afterward","reading":"There is both a conversation and action afterward. This can gradually strengthen trust: you do not have to rely on a promise alone to judge whether you are being considered. Their actual follow-through becomes information you can carry into the next uncertain moment.","preview":"There is both a conversation and action afterward.","reviewZh":{"label":"一起商量能做到什么，之后通常会履行。","reading":"对方的回应有商量，也有后续行动。这样的经历可以慢慢增加信任：你不用只靠一句承诺判断自己是否被在意。你可以把这些实际行动，作为判断关系是否可靠的一部分。"}}},{"optionId":"q16-b","label":"Agree warmly in the moment, but often do not follow through.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q16-b","tag":"needs_empty_promises","title":"A warm promise can keep you waiting much longer","reading":"A warm yes can renew your hope, and repeated non-delivery can disappoint you again. You may keep waiting because the promise felt sincere, while the original problem does not change. Brief hope followed by another letdown can make it increasingly difficult to decide how long to keep waiting.","preview":"A warm yes can renew your hope, and repeated non-delivery can disappoint you again.","reviewZh":{"label":"当时答应得很好，之后却常常没有做到。","reading":"短暂的答应会让你重新有期待，反复落空又让你失望。你可能因为一次温暖的回应继续等，却发现相同的问题始终没有改变。短暂的希望与反复的落空，可能让你越来越难判断自己还要等多久。"}}},{"optionId":"q16-c","label":"Dismiss the request or say I am asking for too much.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q16-c","tag":"needs_dismissed","title":"Do your needs always have to earn permission first?","reading":"When needs are repeatedly dismissed, you may begin to doubt whether you should ask at all, or become more urgent about being heard. The cost can be spending more and more energy proving that your request is reasonable, with very little actual response to the need itself.","preview":"When needs are repeatedly dismissed, you may begin to doubt whether you should ask at all, or become more urgent about being heard.","reviewZh":{"label":"觉得我要求太多，或者把这个需要直接带过去。","reading":"当需要经常被否定，你可能开始怀疑自己是不是不该开口，也可能越说越急。关系的代价可能在于：你越来越忙着证明需要合理，却很少真正得到回应。"}}},{"optionId":"q16-d","label":"Need time, then return with a clear answer or another workable option.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q16-d","tag":"needs_clear_delay","title":"A later answer with follow-through is different from a broken promise","reading":"The response is not immediate, but there is consideration and an answer. This is different from a delay with no follow-up. Even if you do not get everything you hoped for, a clear explanation gives you something real to consider instead of leaving you to guess indefinitely.","preview":"The response is not immediate, but there is consideration and an answer.","reviewZh":{"label":"需要一些时间，但之后会给出明确答复或替代办法。","reading":"对方没有立刻满足，却愿意认真考虑并给出交代。这更接近有边界的回应。等待里有明确的交代，你就有更多信息判断对方是否认真对待。"}}},{"optionId":"q16-skip","label":"I do not remember / Not applicable / Prefer not to answer","microcopy":"","meaning":"","projection":"","fixed":{"id":"q16-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不记得／不适用／暂不想回答","reading":"不补写这段经历，不使用依恋类型猜测答案。报告会明确这部分信息不足，并使用其他已经回答的线索。"}}}]','{"version":"attachment-fixed-v2","kind":"relationship","domain":"Your relationship","sourceNumber":12}',16,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions(id,test_id,kicker,prompt,atlas_path,options_json,report_config_json,position,active) VALUES ('attachment-style-fixed-v2-q17','attachment-style','Family and experience','Growing up, when something upset or frightened you, what usually happened when you asked your main caregiver for help?','','[{"optionId":"q17-a","label":"Someone usually listened and tried to give me the support I needed.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q17-a","tag":"family_help_available","title":"You have known what it is like for a need to receive a response","reading":"You remember someone being willing to understand your feelings and take part in helping. Those experiences may have made asking feel possible. If relying on others is difficult now, later experiences may also matter. Having received support and finding it hard to feel safe today can both be part of your story.","preview":"You remember someone being willing to understand your feelings and take part in helping.","reviewZh":{"label":"通常有人认真听，也会尽量给我需要的支持。","reading":"你记得的回应里，有人愿意参与解决困难，也愿意了解你的感受。这样的经历可能让你更容易相信，需要可以被说出来。如果你现在仍很难求助，也可能与后来的经历有关；有过支持和现在不易放心，可以同时存在。"}}},{"optionId":"q17-b","label":"Sometimes they helped and sometimes they did not; it was hard to predict.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q17-b","tag":"family_help_unpredictable","title":"You may have learned to check their mood before you asked","reading":"When a similar need received different responses, you may have learned to observe before asking. Later, a small change in someone close to you can quickly draw your attention: is this still a moment when I can turn toward them? The skill of noticing can remain active even when you wish you could simply relax.","preview":"When a similar need received different responses, you may have learned to observe before asking.","reviewZh":{"label":"有时会帮助我，有时不理我，很难提前知道。","reading":"当同样的需要得到不同的回应，你可能逐渐学会先观察，再决定要不要开口。后来，亲近的人一点语气变化，也可能让你马上留意：现在还能不能向对方靠近？"}}},{"optionId":"q17-c","label":"Asking rarely brought the support I needed, so I usually handled it myself.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q17-c","tag":"family_help_unavailable","title":"When did relying on yourself start to feel like the only real option?","reading":"If you repeatedly asked a parent or caregiver for help and found that they could not provide the support you needed, you may have reached a conclusion: asking does not change much; in the end, I have to rely on myself. You learned to work through hurt alone and solve difficulties yourself. Later, even in a close relationship, depending on someone may rarely feel like an available choice.","preview":"If you repeatedly asked a parent or caregiver for help and found that they could not provide the support you needed, you may have reached a conclusion: asking does not change much; in the end, I have to rely on myself.","reviewZh":{"label":"找他们也很难得到需要的帮助，最后通常还是自己处理。","reading":"如果小时候，你多次向父母或主要照顾者寻求帮助，却发现他们也无法给你需要的支持，你可能慢慢形成一个想法：说了也没用，最后还是得靠自己。后来，难过的时候，你学会自己消化；遇到困难，你习惯自己解决。即使进入亲密关系，也很少把“依靠对方”当作一个选择。"}}},{"optionId":"q17-d","label":"Asking sometimes brought criticism and left me feeling worse.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q17-d","tag":"family_help_backfires","title":"You want help and worry about what happens after you ask","reading":"If asking could make things harder, you may have started considering the consequences before speaking. The wish for support remained, but the question of whether asking would make things worse could stop it. Later, wanting to come closer to someone may also bring an immediate urge to protect what they can see.","preview":"If asking could make things harder, you may have started considering the consequences before speaking.","reviewZh":{"label":"求助有时会换来责备，让我比开口前更难受。","reading":"如果求助可能带来更多责备，你可能逐渐在开口前先考虑后果。需要支持的感觉仍然存在，却会被“说出来会不会更糟”挡住。后来，你也可能在想靠近一个人时，同时开始保护自己。"}}},{"optionId":"q17-skip","label":"I do not remember / Not applicable / Prefer not to answer","microcopy":"","meaning":"","projection":"","fixed":{"id":"q17-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不记得／不适用／暂不想回答","reading":"不补写这段经历，不使用依恋类型猜测答案。报告会明确这部分信息不足，并使用其他已经回答的线索。"}}}]','{"version":"attachment-fixed-v2","kind":"family","domain":"Family and experience","sourceNumber":15}',17,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions(id,test_id,kicker,prompt,atlas_path,options_json,report_config_json,position,active) VALUES ('attachment-style-fixed-v2-q18','attachment-style','Family and experience','Growing up, what felt most familiar when you wanted attention, company, or help?','','[{"optionId":"q18-a","label":"I could usually ask directly and get a clear response.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q18-a","tag":"family_direct","title":"There were times when your needs could be said directly","reading":"You remember asking being followed by a response you could understand. Not every request had to be granted for you to know where you stood. Even if you do not always feel settled now, those experiences of a clear response remain part of what you know relationships can offer.","preview":"You remember asking being followed by a response you could understand.","reviewZh":{"label":"通常可以直接说，对方也会给我清楚的回应。","reading":"你比较熟悉直接表达后的清楚回应。即使对方不能每次满足，也不必一直靠猜来理解。即使现在不总能安心，这些清楚回应的经历，也仍然是你对关系的经验的一部分。"}}},{"optionId":"q18-b","label":"I checked the adult''s mood before deciding whether to ask.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q18-b","tag":"family_mood","title":"You check how they are before making room for yourself","reading":"You may have practiced reading other people very early. In close relationships, the sequence can still feel familiar: work out whether they want to listen, then decide whether your need can appear. Over time, managing their mood may come more naturally than describing what you need yourself.","preview":"You may have practiced reading other people very early.","reviewZh":{"label":"先看大人的心情，再决定要不要说。","reading":"你可能很早就练习观察别人的状态。这个习惯在亲密关系里仍可能很熟悉：先判断对方愿不愿意听，再决定自己的需要该不该出现。久了，照顾对方的情绪可能比表达自己更自然。"}}},{"optionId":"q18-c","label":"I was praised for being independent and not asking for much.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q18-c","tag":"family_independence_rewarded","title":"When did needing less become part of being good?","reading":"If being easy or grown-up often meant needing little, carrying things yourself may have become a way to keep relationships comfortable. Later, others may see independence without seeing the effort it takes. They may not realize that you also become tired and sometimes wish someone would take care of you.","preview":"If being easy or grown-up often meant needing little, carrying things yourself may have become a way to keep relationships comfortable.","reviewZh":{"label":"少提要求、自己处理时，更容易被夸懂事。","reading":"如果“懂事”常常意味着少麻烦别人，你可能逐渐把自己承担当成维持好关系的方式。后来，别人看到的是你很独立，却不一定知道你也会累，也希望被照顾。"}}},{"optionId":"q18-d","label":"I found it easier to get attention after doing well or being helpful.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q18-d","tag":"family_earned_attention","title":"Do you feel you have to offer something before you can need something?","reading":"If attention was closely linked to achievement or usefulness, doing more may have become a familiar way to feel important. In a relationship, you might keep giving without finding out whether your needs also matter when you are not earning your place through effort.","preview":"If attention was closely linked to achievement or usefulness, doing more may have become a familiar way to feel important.","reviewZh":{"label":"表现好、做出成绩或帮了忙，更容易得到关注。","reading":"如果被关注常和表现联系在一起，你可能更容易通过付出证明自己的重要。进入关系后，这可能表现为不断做得更多，却很少停下来确认：不付出的时候，我的需要是否也值得被认真对待？"}}},{"optionId":"q18-skip","label":"I do not remember / Not applicable / Prefer not to answer","microcopy":"","meaning":"","projection":"","fixed":{"id":"q18-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不记得／不适用／暂不想回答","reading":"不补写这段经历，不使用依恋类型猜测答案。报告会明确这部分信息不足，并使用其他已经回答的线索。"}}}]','{"version":"attachment-fixed-v2","kind":"family","domain":"Family and experience","sourceNumber":16}',18,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions(id,test_id,kicker,prompt,atlas_path,options_json,report_config_json,position,active) VALUES ('attachment-style-fixed-v2-q19','attachment-style','Family and experience','Growing up, what usually happened after a disagreement at home?','','[{"optionId":"q19-a","label":"We spoke again, and there was a chance to discuss what happened.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q19-a","tag":"family_repair","title":"A disagreement could still lead back to being heard","reading":"You may have known that conflict could be followed by renewed contact and a conversation. That gives you a reference for what repair can look like. It does not mean that disagreements never frighten or upset you; it means an argument did not always have to be the end of being heard.","preview":"You may have known that conflict could be followed by renewed contact and a conversation.","reviewZh":{"label":"之后会重新说话，问题也有机会被谈清楚。","reading":"你可能较早接触过一种经验：有矛盾，关系仍然可以继续沟通。这样的经历能为之后的修复提供参照，但不代表你每次冲突都不会害怕或难受。"}}},{"optionId":"q19-b","label":"Someone stopped speaking for a long time, and I did not know when it would end.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q19-b","tag":"family_silent","title":"Silence without a clear ending can carry extra weight","reading":"When silence had no clear ending, waiting may have become especially uncomfortable. Later, a pause in contact can make the return feel urgent. You may also recognize silence as a familiar way to respond yourself. What matters is which of those reactions actually appears in your answers today.","preview":"When silence had no clear ending, waiting may have become especially uncomfortable.","reviewZh":{"label":"有人长时间不说话，我不知道什么时候才会结束。","reading":"如果沉默何时结束一直不清楚，等待可能成为一种很难受的经验。后来，伴侣暂时没有回应时，你可能会特别在意何时能恢复联系；也可能把沉默当成自己熟悉的应对方式。"}}},{"optionId":"q19-c","label":"Things went back to normal, but we rarely discussed what had happened.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q19-c","tag":"family_unspoken","title":"Where did the unspoken hurt go after everyone calmed down?","reading":"Calm returning did not necessarily mean that hurt had been understood. You may have become familiar with letting things pass without talking them through. Later, no longer arguing can feel like having repaired the relationship, even when one person still carries something that was never heard.","preview":"Calm returning did not necessarily mean that hurt had been understood.","reviewZh":{"label":"过一会儿就像没事一样，但很少再谈发生了什么。","reading":"家里恢复平静，并不一定意味着委屈被说清。你可能因此熟悉“过去就算了”的相处方式。进入关系后，有时会把不再争执当成已经和好，却留下没有被听见的部分。"}}},{"optionId":"q19-d","label":"I often calmed people down or gave in so we could get along again.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q19-d","tag":"family_peacemaker","title":"Are you still the one responsible for making everyone feel okay?","reading":"If you often helped restore the atmosphere, looking after the relationship before your own feelings may feel natural. Later, you may become the person who repeatedly initiates repair. The hidden cost is how little room remains to notice whether the other person is sharing that responsibility.","preview":"If you often helped restore the atmosphere, looking after the relationship before your own feelings may feel natural.","reviewZh":{"label":"我经常先安抚大家、主动让步，让气氛恢复。","reading":"如果你常常承担缓和气氛的角色，你可能很熟悉先顾全关系，再处理自己的感受。长大后，这种习惯可能让你一次次主动修复，却很少确认对方有没有一起承担。"}}},{"optionId":"q19-skip","label":"I do not remember / Not applicable / Prefer not to answer","microcopy":"","meaning":"","projection":"","fixed":{"id":"q19-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不记得／不适用／暂不想回答","reading":"不补写这段经历，不使用依恋类型猜测答案。报告会明确这部分信息不足，并使用其他已经回答的线索。"}}}]','{"version":"attachment-fixed-v2","kind":"family","domain":"Family and experience","sourceNumber":19}',19,0) ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions(id,test_id,kicker,prompt,atlas_path,options_json,report_config_json,position,active) VALUES ('attachment-style-fixed-v2-q20','attachment-style','Family and experience','Which past romantic relationship experience most changed how you respond to closeness now?','','[{"optionId":"q20-a","label":"A relationship suddenly became distant or ended without much explanation.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q20-a","tag":"history_abrupt","title":"An unexplained ending can change the way you wait","reading":"Losing contact without much explanation can make later changes more noticeable. You might look for distance sooner, or invest less before it can hurt. Experiences after childhood can also change how you understand closeness; you do not need to fit every current reaction into a single early family story.","preview":"Losing contact without much explanation can make later changes more noticeable.","reviewZh":{"label":"一段关系突然变冷或结束，对方没有给多少解释。","reading":"突然失去联系或缺少交代，可能让之后的变化变得格外显眼。你可能会更快察觉疏远，也可能提前减少投入。后来发生的事，也可能改变了你现在理解亲近的方式。"}}},{"optionId":"q20-b","label":"Promises were repeatedly made and not kept.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q20-b","tag":"history_promises","title":"A promise may no longer be enough to let you hope","reading":"Repeated broken promises can make words less reassuring. Even when someone means what they say now, you may want more confirmation, watch for action, or hold back your expectations. It can take observable follow-through before a promise begins to feel like something you can rely on.","preview":"Repeated broken promises can make words less reassuring.","reviewZh":{"label":"对方经常许下承诺，却一次次没有做到。","reading":"反复失信可能让一句承诺越来越难让你安心。后来，即使有人认真答应，你也可能更想确认、继续观察，或者先不抱希望。一句答应能不能成为信任，可能要经过更多实际行动来确认。"}}},{"optionId":"q20-c","label":"My privacy, boundaries, or vulnerability were not respected.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q20-c","tag":"history_boundaries","title":"Your caution may be connected to trust that was not respected","reading":"If trust you offered was not respected, saying less and keeping distance may have become ways to protect yourself. You may pay closer attention to how someone handles your limits and whether what you share is treated carefully. This experience can matter without needing to assume additional details about what happened.","preview":"If trust you offered was not respected, saying less and keeping distance may have become ways to protect yourself.","reviewZh":{"label":"我的隐私、界限，或说过的脆弱没有被尊重。","reading":"如果你曾经交出去的信任没有被尊重，之后少说一点、留一点距离，可能成了保护自己的方式。你会更加在意对方怎样对待你的界限，以及说出口的感受能不能被尊重。"}}},{"optionId":"q20-d","label":"Consistent care gradually helped me feel safer being close.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q20-d","tag":"history_reliable","title":"A later relationship may have helped you learn to feel safer","reading":"You remember a later relationship offering reliable responses over time. That may have helped you become more willing to speak and depend on someone, even while some older habits remained. You can still have moments of doubt and also have become more willing to try trusting than you were before.","preview":"You remember a later relationship offering reliable responses over time.","reviewZh":{"label":"有人长期可靠地回应我，让我逐渐敢于亲近。","reading":"你记得的后来经历里，有持续的可靠回应。这样的相处可能让你慢慢愿意表达和依靠，即使有些旧习惯还在。你可以仍然有不安，也已经比过去更愿意尝试信任。"}}},{"optionId":"q20-none","label":"No experience stands out as changing this for me.","microcopy":"","meaning":"","projection":"","fixed":{"id":"q20-none","tag":"history_none","title":"No specific turning point was identified","reading":"You did not identify a particular turning point. This does not mean that nothing difficult ever happened, and the report will not invent an experience to fill the gap.","preview":"You did not identify a particular turning point.","reviewZh":{"label":"没有明显改变我的经历","reading":"没有选出明确的后续经历，不等于从未遇到困难。报告不会为这一章编造转折，也不会把缺少经历当成任何一种依恋类型。"}}},{"optionId":"q20-skip","label":"I do not remember / Not applicable / Prefer not to answer","microcopy":"","meaning":"","projection":"","fixed":{"id":"q20-skip","tag":"skip","title":"This part stays open","reading":"You did not provide enough information to interpret this situation. No personal history or reaction is filled in for this answer.","preview":"You did not provide enough information to interpret this situation.","reviewZh":{"label":"不记得／不适用／暂不想回答","reading":"不补写这段经历，不使用依恋类型猜测答案。报告会明确这部分信息不足，并使用其他已经回答的线索。"}}}]','{"version":"attachment-fixed-v2","kind":"history","domain":"Family and experience","sourceNumber":18}',20,0) ON CONFLICT(id) DO NOTHING;
